() => {
  const nav = performance.getEntriesByType('navigation')[0];
  const paint = performance.getEntriesByType('paint');
  const resources = performance.getEntriesByType('resource');

  const navTiming = {
    dns: Math.round(nav.domainLookupEnd - nav.domainLookupStart),
    tcp: Math.round(nav.connectEnd - nav.connectStart),
    ttfb: Math.round(nav.responseStart - nav.requestStart),
    htmlDownload: Math.round(nav.responseEnd - nav.responseStart),
    domInteractive: Math.round(nav.domInteractive),
    domComplete: Math.round(nav.domComplete),
    loadEvent: Math.round(nav.loadEventEnd),
  };

  const paintTimings = Object.fromEntries(paint.map(p => [p.name, Math.round(p.startTime)]));

  const slowResources = resources
    .map(r => ({
      name: r.name.replace('https://guest.ofrules.com', ''),
      duration: Math.round(r.duration),
      size: Math.round((r.transferSize || 0) / 1024) + 'KB',
      type: r.initiatorType,
    }))
    .sort((a, b) => b.duration - a.duration)
    .slice(0, 15);

  return { navTiming, paintTimings, slowResources };
}

