import { getStorage, ref, getDownloadURL } from 'firebase/storage'
import { firebaseApp } from '@/services/firebase-config'

const storage = getStorage(firebaseApp)

/**
 * Get download URL for a Firebase Storage file
 * @param gsUrl - Firebase Storage URL in format: gs://bucket-name/path/to/file
 * @returns Promise with the download URL
 */
export async function getStorageUrl(gsUrl: string): Promise<string> {
  try {
    // Extract the path from gs:// URL
    const path = gsUrl.replace(/^gs:\/\/[^/]+\//, '')

    const storageRef = ref(storage, path)
    const url = await getDownloadURL(storageRef)

    return url
  } catch (error) {
    console.error('Error getting storage URL:', error)
    throw error
  }
}

/**
 * Convert gs:// URL to https:// URL without authentication (for public files)
 * @param gsUrl - Firebase Storage URL in format: gs://bucket-name/path/to/file
 * @returns HTTPS URL
 */
export function gsToHttps(gsUrl: string): string {
  // Extract bucket and path from gs:// URL
  const match = gsUrl.match(/^gs:\/\/([^/]+)\/(.+)$/)

  if (!match) {
    return gsUrl
  }

  const [, bucket, path] = match
  const encodedPath = path.split('/').map(encodeURIComponent).join('%2F')

  return `https://firebasestorage.googleapis.com/v0/b/${bucket}/o/${encodedPath}?alt=media`
}

export interface AssociativeArray {
  [key: string]: Object
}

export interface ExtFeedbackAction {
  building: Building
  checkpointName: string
  actionData: any[]
  compoundActionList?: any[]
  actionType: string
}

export interface ActionTextsEntity {
  lang: string
  texts: Texts
}

export interface Texts {
  title: string
  buttonOk: string
  buttonBack: string
  successTitle: string
  successText: string
  cancelTitle: string
  cancelText: string
  text: string
  buttonCTA: string
}

/**
 * Base interface for common fields across all action language types
 */
export interface BaseActionLanguage {
  // Core navigation
  buttonOk: string
  buttonBack: string
  buttonBackMenu: string
  buttonCTA?: string

  // Success state
  successTitle: string
  successText: string
  successTexts?: string[]
  successText2?: string

  // Cancel state (optional)
  cancelTitle?: string
  cancelText?: string

  // List view (for menu display)
  listTitle?: string
  listText?: string
  listTexts?: string[]
  listBottomText?: string
  listCTAButton?: string
  listCTASecondaryButton?: string
  listLinks?: Array<{
    text: string
    url: string
  }>
  listTags?: string[] // Filter chips/tags (e.g., ["Tickets", "Popular", "2 km"])

  // Optional description
  description?: string
}

export interface BuildingInfoSection {
  title: string
  text?: string
  texts?: string[]
}

export interface BuildingInfo {
  [lang: string]: {
    sections: BuildingInfoSection[]
  }
}

export interface Building {
  name: string
  language: string
  website?: string
  googleUrl?: string

  // Header design fields (Figma "Hlavná stránka V1")
  headerImage?: string // URL to building/room image for header
  headerTags?: string[] // Tags shown below header image (e.g., ["Checkout: 14:00", "Wifi"])

  // WiFi info (Figma "Hlavná stránka Wifi")
  wifi?: {
    [lang: string]: {
      name: string
      password: string
    }
  }

  // Building info sections (Figma "Hlavná stránka INFO")
  info?: BuildingInfo
}

export interface OccurenceAction extends BaseActionLanguage {
  title: string
  text: string
}

export interface OrderAction extends BaseActionLanguage {
  // Form fields
  title: string
  text: string
  texts?: string[]
  bottomText?: string
  inputText?: string

  // CTA
  ctaText?: string

  // Reservation
  reservation?: string
  reservationText?: string
  reservationFull?: string
  availableCapacity?: string
  today?: string
  tomorrow?: string

  // Phone input
  phoneText?: string
  phoneInput?: string
  typePhone?: string
  errorPhone: string

  // Email input
  emailText?: string
  emailInput?: string
  typeEmail?: string
  errorEmail: string

  // Note input
  noteText?: string
  noteInput?: string
  typeNote?: string
  errorNote: string

  // Second note
  noteText2?: string
  noteInput2?: string
  typeNote2?: string
  errorNote2: string

  // Number input
  numberInputText?: string
  typeNumberText?: string

  // String input
  stringInputText?: string
  labelText?: string

  // Selection
  selectionText?: string
  selectOptions?: string[]

  // Checkboxes
  checkboxes?: string[]
  checkboxesTexts?: string[]

  // Tags
  leftTags?: string[]
  rightTags?: string[]
}

export interface QuestionAction extends BaseActionLanguage {
  title: string
  text: string
  secondTitle: string
  secondText: string
  buttonNext: string

  // Question input
  inputQuestionText: string
  typeQuestionText: string
  requiredText: string

  // Contact fields
  phoneText: string
  typePhone: string
  errorPhone: string

  mailText: string
  typeEmail: string
  errorEmail: string
}

/**
 * Structure for questionnaire items in reviews
 */
export interface ReviewQuestionItem {
  question: string
  answers: string[]
  allowOther?: boolean
  otherText?: string
}

export interface ReviewAction extends BaseActionLanguage {
  title: string
  text: string
  buttonNext: string

  // Rating
  requiredScore: string

  // Input
  inputText: string
  typeText: string

  // Email (optional)
  mailText?: string
  typeEmail?: string
  errorEmail: string

  // Contact based on rating
  contactPositiveTitle?: string
  contactPositiveText?: string
  contactNegativeTitle?: string
  contactNegativeText?: string

  // Questionnaire
  textQuestion?: string
  positiveQuestions?: ReviewQuestionItem[]
  negativeQuestions?: ReviewQuestionItem[]
}

/**
 * Link action for external navigation and information display
 * Only uses list view fields from BaseActionLanguage (no form fields)
 */
export interface LinkAction extends BaseActionLanguage {
  // Link actions only use inherited list view fields:
  // - listTitle
  // - listText
  // - listTexts
  // - listBottomText
  // - listCTAButton
  // - listLinks
}

export interface DateReservation {
  date: string
  freeCapacity?: number
}

export interface ReservationTime {
  start: string
  end: string
  dateReserved?: string // Deprecated: kept for backward compatibility
  type?: string // Deprecated: kept for backward compatibility
  capacity?: number
  freeCapacity?: number // Deprecated: kept for backward compatibility
  reservations?: DateReservation[] // New: array of date-based reservations
}

