import {
  onCall,
  HttpsError,
  CallableRequest,
  FunctionsErrorCode,
  CallableOptions,
} from "firebase-functions/v2/https";
import { logger } from "firebase-functions/v2";
import { HttpError, BodyValidationError } from "./errors";
import { Sentry } from "../sentry";

/**
 * Sanitizes request data for logging by truncating large values
 */
function sanitizeForLogging(
  data: unknown,
  maxStringLength = 200,
  maxArrayItems = 3
): unknown {
  if (data === null || data === undefined) return data;
  if (typeof data === "string") {
    return data.length > maxStringLength
      ? `${data.substring(0, maxStringLength)}... (truncated, ${data.length} chars)`
      : data;
  }
  if (Array.isArray(data)) {
    const truncated = data
      .slice(0, maxArrayItems)
      .map((item) => sanitizeForLogging(item, maxStringLength, maxArrayItems));
    if (data.length > maxArrayItems) {
      return [
        ...truncated,
        `... and ${data.length - maxArrayItems} more items`,
      ];
    }

    return truncated;
  }
  if (typeof data === "object") {
    const sanitized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(data)) {
      sanitized[key] = sanitizeForLogging(
        value,
        maxStringLength,
        maxArrayItems
      );
    }

    return sanitized;
  }

  return data;
}

/**
 * Maps HTTP status codes to Firebase HttpsError codes
 */
function getHttpsErrorCode(status: number): FunctionsErrorCode {
  switch (status) {
    case 400:
      return "invalid-argument";
    case 401:
      return "unauthenticated";
    case 403:
      return "permission-denied";
    case 404:
      return "not-found";
    case 409:
      return "already-exists";
    case 412:
      return "failed-precondition";
    default:
      return "internal";
  }
}

/**
 * Wrapper for onCall that handles custom HttpError instances
 * and converts them to Firebase HttpsError for consistent error handling.
 *
 * @param options - CallableOptions for the function
 * @param handler - The function handler
 * @param functionName - Optional name for better error logging. If not provided,
 *                       attempts to extract from handler.name or uses "unknown"
 */
export function onCallWithErrorHandler(
  options: CallableOptions,
  handler: (request: CallableRequest) => Promise<void | unknown>,
  functionName?: string
) {
  const fnName = functionName || handler.name || "unknown";

  return onCall(options, async (request) => {
    // Auth check
    if (process.env.FUNCTIONS_EMULATOR !== "true" && !request.auth) {
      throw new HttpsError(
        "unauthenticated",
        "The function must be called while authenticated."
      );
    }

    try {
      return await handler(request);
    } catch (error) {
      // Handle body validation errors with detailed Zod validation issues
      if (error instanceof BodyValidationError) {
        const issues = error.error.issues;
        const formattedIssues = issues.map((issue) => {
          const path = issue.path.join(".") || "(root)";

          // Add more context for type mismatches
          if (issue.code === "invalid_type") {
            const { expected, input } = issue;
            const receivedType = input === null ? "null" : typeof input;

            return `${path}: expected ${expected}, received ${receivedType}`;
          }

          return `${path}: ${issue.message}`;
        });

        const errorMessage = `[${fnName}] Validation failed:\n  - ${formattedIssues.join("\n  - ")}`;

        // Log detailed error with received data for debugging (no stack trace - it's a client error)
        logger.error(errorMessage, {
          function: fnName,
          receivedData: sanitizeForLogging(request.data),
        });

        throw new HttpsError("invalid-argument", errorMessage, {
          function: fnName,
          issues: issues.map((i) => ({
            path: i.path.join(".") || "(root)",
            message: i.message,
            code: i.code,
            expected: "expected" in i ? i.expected : undefined,
            received: "input" in i ? typeof i.input : undefined,
          })),
        });
      }

      // Handle all custom HttpError instances
      if (error instanceof HttpError) {
        logger.error(`[${fnName}] [${error.status}] ${error.message}`);
        if (error.status >= 500) {
          Sentry.captureException(error);
        }
        throw new HttpsError(getHttpsErrorCode(error.status), error.message);
      }

      // Handle unexpected errors (keep stack trace for these - they're bugs)
      logger.error(`[${fnName}] Unhandled error:`, error);
      Sentry.captureException(error);
      throw new HttpsError("internal", "Internal server error");
    }
  });
}

