/**
 * Helper method for getting serviceID
 * @param {DocumentReference} buildingRef
 * @param {string} serviceType
 * @return {string} service ID
 */
export async function getServiceIDByType(
  buildingRef: DocumentReference,
  serviceType: string
): Promise<undefined | DocumentReference<DocumentData>> {
  const serviceSnaps = await db
    .collection(collectionNames.servicesCN)
    .where("building", "==", buildingRef)
    .get();
  const service = serviceSnaps.docs.find(
    (snap) => snap.data().type == serviceType
  );

  return service?.ref;
}

