import { logger } from "firebase-functions/v2";
import {
  BodyValidationError,
  HttpError,
  QueryValidationError,
  ResponseValidationError,
} from "./errors";
import * as express from "express";
import { prettifyError } from "zod";

/**
 * Unified error handler for all API endpoints
 * Handles custom HttpError instances and provides consistent error responses
 */
export function handleAPIError(error: unknown, res: express.Response): void {
  // Handle response validation errors (development only)
  if (error instanceof ResponseValidationError) {
    logger.error("Response validation failed:", error.message);

    res.status(500).send({
      message: "Internal server error: Response validation failed",
      errors: error.validationErrors.issues,
    });

    return;
  }

  // Handle body validation errors with detailed Zod validation issues
  if (error instanceof BodyValidationError) {
    logger.error("Body validation failed\n", prettifyError(error.error));

    res.status(error.status).send({
      message: "Validation failed",
      errors: error.error.issues,
    });

    return;
  }

  // Handle query parameter validation errors
  if (error instanceof QueryValidationError) {
    logger.error("Query validation failed:", error.message);

    res.status(error.status).send({
      message: error.message,
    });

    return;
  }

  // Handle all custom HttpError instances
  if (error instanceof HttpError) {
    logger.error(`[${error.status}]`, error.message);

    res.status(error.status).send({ message: error.message });

    return;
  }

  // Handle unexpected errors
  logger.error("Unhandled error:", error);
  res.status(500).send({ message: "Internal server error" });
}

