    11→
    12→import { Session, SessionEvent } from "./sessionSchemas";
    13→
    14→const db = getFirestore();
    15→
    16→export class SessionRepository {
    17→  /**
    18→   * Create a new session in the building
    19→   */
    20→  static async createSession(buildingID: string): Promise<string> {
    21→    const buildingRef = db
    22→      .collection(collectionNames.buildingsCN)
    23→      .doc(buildingID);
    24→    const now = new Date();
    25→    const sessionID = randomBytes(32).toString("hex");
    26→
    27→    const sessionData: Session = {
    28→      events: [],
    29→      guests: [],
    30→      lastUsedAt: now,
    31→      createdAt: now,
    32→    };
    33→
    34→    const sessionRef = buildingRef
    35→      .collection(collectionNames.sessionsCN)
    36→      .doc(sessionID)
    37→      .withConverter(sessionConverter);
    38→
    39→    await sessionRef.set(sessionData);
    40→
    41→    logger.debug(`Created new session: ${sessionRef.id}`);
    42→
    43→    return sessionRef.id;
    44→  }
    45→
    46→  /**
    47→   * Get session by ID
    48→   */
    49→  static async getSession(
    50→    buildingID: string,
    51→    sessionID: string
    52→  ): Promise<Session | null> {
    53→    const sessionRef = db
    54→      .collection(collectionNames.buildingsCN)
    55→      .doc(buildingID)
    56→      .collection(collectionNames.sessionsCN)
    57→      .doc(sessionID)
    58→      .withConverter(sessionConverter);
    59→
    60→    const sessionSnap = await sessionRef.get();
    61→    if (!sessionSnap.exists) {
    62→      return null;
    63→    }
    64→
    65→    return sessionSnap.data() ?? null;
    66→  }
    67→
    68→  /**
    69→   * Update session's lastUsedAt timestamp
    70→   */
    71→  static async touchSession(
    72→    buildingID: string,
    73→    sessionID: string
    74→  ): Promise<void> {
    75→    const sessionRef = db
    76→      .collection(collectionNames.buildingsCN)
    77→      .doc(buildingID)
    78→      .collection(collectionNames.sessionsCN)
    79→      .doc(sessionID)
    80→      .withConverter(sessionConverter);
    81→
    82→    await sessionRef.update({
    83→      lastUsedAt: new Date(),
    84→    });
    85→  }
    86→
    87→  /**
    88→   * Add an event to the session
    89→   */
    90→  static async addEvent(
    91→    buildingID: string,
    92→    sessionID: string,
    93→    event: SessionEvent
    94→  ): Promise<void> {
    95→    const sessionRef = db
    96→      .collection(collectionNames.buildingsCN)
    97→      .doc(buildingID)
    98→      .collection(collectionNames.sessionsCN)
    99→      .doc(sessionID)
   100→      .withConverter(sessionConverter);
   101→
   102→    await sessionRef.update({
   103→      events: FieldValue.arrayUnion(event),
   104→      lastUsedAt: new Date(),
   105→    });
   106→
   107→    logger.debug(
   108→      `Added ${event.type} event to session ${sessionID} for action ${event.action.path}`
   109→    );
   110→  }
   111→
   112→  /**
   113→   * Add a guest reference to the session
   114→   */
   115→  static async addGuest(
   116→    buildingID: string,
   117→    sessionID: string,
   118→    guestRef: DocumentReference
   119→  ): Promise<void> {
   120→    const sessionRef = db
   121→      .collection(collectionNames.buildingsCN)
   122→      .doc(buildingID)
   123→      .collection(collectionNames.sessionsCN)
   124→      .doc(sessionID)
   125→      .withConverter(sessionConverter);
   126→
   127→    // Check if guest is already in the session
   128→    const sessionSnap = await sessionRef.get();
   129→    if (!sessionSnap.exists) {
   130→      logger.warn(`Session ${sessionID} not found when adding guest`);
   131→
   132→      return;
   133→    }
   134→
   135→    const sessionData = sessionSnap.data();
   136→    const guestExists = sessionData?.guests.some(
   137→      (g) => g.path === guestRef.path
   138→    );
   139→
   140→    if (!guestExists) {
   141→      await sessionRef.update({
   142→        guests: FieldValue.arrayUnion(guestRef),
   143→        lastUsedAt: new Date(),
   144→      });
   145→
   146→      logger.debug(`Added guest ${guestRef.id} to session ${sessionID}`);
   147→    }
   148→  }
   149→
   150→  /**
   151→   * Check if session exists and is valid
   152→   */
   153→  static async isValidSession(
   154→    buildingID: string,
   155→    sessionID: string
   156→  ): Promise<boolean> {
   157→    const session = await this.getSession(buildingID, sessionID);
   158→
   159→    return session !== null;
   160→  }
   161→}
