    99→      if (actionData?.reservation) {
   100→        const reservation = actionData.reservation;
   101→        const isMultiday = reservation.type === "multiday";
   102→
   103→        // Handle time-slot based reservations (exclusive or with capacity)
   104→        if (reservation.times && Array.isArray(reservation.times)) {
   105→          if (body.selectedOption == null) {
   106→            throw new HttpError(400, "Missing selected option");
   107→          }
   108→
   109→          const selectedTime = reservation.times[body.selectedOption];
   110→          if (!selectedTime) {
   111→            throw new HttpError(400, "Invalid selected option");
   112→          }
   113→
   114→          // Get reservation date based on multiday or single day
