   131→                reservationDate.setDate(reservationDate.getDate() + 1);
   132→              }
   133→            }
   134→            reservationDateStr = reservationDate
   135→              .toLocaleDateString("sk-SK")
   136→              .replace(/\s/g, "");
   137→          }
   138→
