   155→                currentFreeCapacity =
   156→                  existingReservation.freeCapacity ?? selectedTime.capacity;
   157→              } else {
   158→                currentFreeCapacity = selectedTime.capacity;
   159→              }
   160→
   161→              if (currentFreeCapacity < body.selectedNumber) {
   162→                throw new ConflictError(
   163→                  "Not enough capacity available for selected time"
   164→                );
   165→              }
   166→
   167→              // Update or add reservation entry
   168→              const updatedReservations = (
   169→                selectedTime.reservations as DateReservation[]
   170→              ).filter((r: DateReservation) => r.date !== reservationDateStr);
   171→              updatedReservations.push({
   172→                date: reservationDateStr,
   173→                freeCapacity: currentFreeCapacity - body.selectedNumber,
