   243→                    reservation.times[i] = {
   244→                      ...time,
   245→                      reservations: [
   246→                        ...existingReservations,
   247→                        { date: reservationDateStr },
   248→                      ],
   249→                    };
   250→                  }
   251→                }
   252→              }
   253→            } else {
   254→              // Old structure: backward compatibility
   255→              if (selectedTime.dateReserved === reservationDateStr) {
   256→                throw new ConflictError(
   257→                  "Reservation already exists for selected time"
   258→                );
   259→              }
   260→
   261→              // Mark overlapping time slots as reserved
   262→              const selectedStart = selectedTime.start;
   263→              const selectedEnd = selectedTime.end;
   264→
   265→              for (let i = 0; i < reservation.times.length; i++) {
   266→                const time = reservation.times[i];
   267→
   268→                // For multiday, only mark overlapping times of the same type
   269→                if (isMultiday && time.type !== selectedTime.type) {
   270→                  continue;
   271→                }
   272→
   273→                const timeStart = time.start;
   274→                const timeEnd = time.end;
   275→
   276→                // Check if the time range overlaps
