   281→                  };
   282→                }
   283→              }
   284→            }
   285→
   286→            await extActionRef.update({
   287→              reservation: reservation,
   288→            });
   289→          }
   290→          // Handle non-exclusive time slots without capacity (infinite capacity)
   291→          // No database update needed - users can book any time infinitely
   292→        }
   293→        // Handle simple capacity-based reservations (no time slots)
   294→        else if (reservation.capacity !== undefined) {
   295→          if (body.selectedNumber == null) {
   296→            throw new HttpError(400, "Missing selected number");
   297→          }
   298→
   299→          // Get reservation date
   300→          const reservationDate = new Date();
