import { getFirestore } from "firebase-admin/firestore";
import { logger } from "firebase-functions/v2";
import { onRequest } from "firebase-functions/v2/https";
import { phone } from "phone";
import { z } from "zod";
import { baseActionSchema, emailRegex, options } from "../../helpers";
import { handleSession } from "../session/sessionMiddleware";
import { SessionRepository } from "../session/sessionRepository";
import { SessionEventType } from "../session/sessionSchemas";
import {
  BodyValidationError,
  HttpError,
  NotFoundError,
  ConflictError,
} from "../../errorHandling/errors";
import { handleAPIError } from "../../errorHandling/errorHandler";

const db = getFirestore();

interface DateReservation {
  date: string;
  freeCapacity?: number;
}

export const createExternalUserOrder = onRequest(
  options,
  async (request, response) => {
    try {
      logger.info("Create external user order called");

      const questionOrderSchema = baseActionSchema.extend({
        inputs: z.array(z.string()),
        selectedOption: z.nullable(z.number()).optional(),
        selectedDate: z.string().optional(), // Date string for array-based reservations
        selectedNumber: z.nullable(z.number()).optional(),
        note: z.string().optional(),
        phone: z.string().optional(),
        email: z.string().optional(),
      });

      const bodyValidation = questionOrderSchema.safeParse(request.body);
      if (!bodyValidation.success) {
        throw new BodyValidationError(bodyValidation.error);
      }

      const body = bodyValidation.data;

      // Handle session management
      const { sessionID } = await handleSession(
        request,
        response,
        body.buildingId
      );

      let isPhoneValid = !!body.phone; // phone is optional
      let isEmailValid = !!body.email; // email is optional

      if (body.phone) {
        const phoneValidationResult = phone(body.phone, {
          validateMobilePrefix: false,
        });
        logger.debug(phoneValidationResult);
        if (phoneValidationResult.isValid) {
          logger.info("Phone is valid");
          isPhoneValid = true;
        }
      }

      if (body.email) {
        if (emailRegex.test(body.email)) {
          logger.info("Email is valid");
          isEmailValid = true;
        }
      }

      const buildingRef = db.collection("Buildings").doc(body.buildingId);
      const buildingSnap = await buildingRef.get();
      if (!buildingSnap.exists) {
        throw new NotFoundError("Building", body.buildingId);
      }
      const cpRef = buildingRef
        .collection("checkpoints")
        .doc(body.checkpointId);
      const cpSnap = await cpRef.get();
      if (!cpSnap.exists) {
        throw new NotFoundError("Checkpoint", body.checkpointId);
      }

      const extActionRef = db.doc(body.extActionPath);
      const extActionSnap = await extActionRef.get();
      if (!extActionSnap.exists) {
        logger.debug(`Action (${body.extActionPath}) not found`);
        throw new NotFoundError("Action", body.extActionPath);
      }

      const actionData = extActionSnap.data();

      // Handle reservation logic
      if (actionData?.reservation) {
        const reservation = actionData.reservation;
        const isMultiday = reservation.type === "multiday";

        // Handle time-slot based reservations (exclusive or with capacity)
        if (reservation.times && Array.isArray(reservation.times)) {
          if (body.selectedOption == null) {
            throw new HttpError(400, "Missing selected option");
          }

          const selectedTime = reservation.times[body.selectedOption];
          if (!selectedTime) {
            throw new HttpError(400, "Invalid selected option");
          }

          // Get reservation date based on multiday or single day
          let reservationDateStr: string;

          // For new array-based structure, use the selectedDate sent from frontend
          if (body.selectedDate) {
            reservationDateStr = body.selectedDate;
          } else {
            // For old structure, calculate date from type field (backward compatibility)
            const reservationDate = new Date();
            if (isMultiday) {
              // For multiday, use the type from the selected time slot (backward compatibility)
              if (selectedTime.type === "tomorrow") {
                reservationDate.setDate(reservationDate.getDate() + 1);
              }
            } else {
              // For single day, use the reservation type
              if (reservation.type === "tomorrow") {
                reservationDate.setDate(reservationDate.getDate() + 1);
              }
            }
            reservationDateStr = reservationDate
              .toLocaleDateString("sk-SK")
              .replace(/\s/g, "");
          }

          // Handle time slots with capacity
          if (selectedTime.capacity !== undefined) {
            if (body.selectedNumber == null) {
              throw new HttpError(400, "Missing selected number");
            }

            let currentFreeCapacity: number;

            // Check if using new array-based structure
            if (selectedTime.reservations !== undefined) {
              // New structure: find reservation for this specific date
              const existingReservation = (
                selectedTime.reservations as DateReservation[]
              ).find((r: DateReservation) => r.date === reservationDateStr);

              if (existingReservation) {
                currentFreeCapacity =
                  existingReservation.freeCapacity ?? selectedTime.capacity;
              } else {
                currentFreeCapacity = selectedTime.capacity;
              }

              if (currentFreeCapacity < body.selectedNumber) {
                throw new ConflictError(
                  "Not enough capacity available for selected time"
                );
              }

              // Update or add reservation entry
              const updatedReservations = (
                selectedTime.reservations as DateReservation[]
              ).filter((r: DateReservation) => r.date !== reservationDateStr);
              updatedReservations.push({
                date: reservationDateStr,
                freeCapacity: currentFreeCapacity - body.selectedNumber,
              });

              reservation.times[body.selectedOption] = {
                ...selectedTime,
                reservations: updatedReservations,
              };
            } else {
              // Old structure: backward compatibility
              currentFreeCapacity =
                selectedTime.dateReserved === reservationDateStr
                  ? selectedTime.freeCapacity!
                  : selectedTime.capacity;

              if (currentFreeCapacity < body.selectedNumber) {
                throw new ConflictError(
                  "Not enough capacity available for selected time"
                );
              }

              reservation.times[body.selectedOption] = {
                ...selectedTime,
                dateReserved: reservationDateStr,
                freeCapacity: currentFreeCapacity - body.selectedNumber,
              };
            }

            await extActionRef.update({
              reservation: reservation,
            });
          }
          // Handle exclusive time slots (no capacity)
          else if (reservation.exclusive) {
            // Check if using new array-based structure
            if (selectedTime.reservations !== undefined) {
              // New structure: check if date exists in reservations array
              const isReserved = (
                selectedTime.reservations as DateReservation[]
              ).some((r: DateReservation) => r.date === reservationDateStr);

              if (isReserved) {
                throw new ConflictError(
                  "Reservation already exists for selected time"
                );
              }

              // Mark overlapping time slots as reserved
              const selectedStart = selectedTime.start;
              const selectedEnd = selectedTime.end;

              for (let i = 0; i < reservation.times.length; i++) {
                const time = reservation.times[i];

                // For multiday, only mark overlapping times of the same type (backward compatibility)
                if (isMultiday && time.type !== selectedTime.type) {
                  continue;
                }

                const timeStart = time.start;
                const timeEnd = time.end;

                // Check if the time range overlaps
                if (timeStart < selectedEnd && timeEnd > selectedStart) {
                  const existingReservations = (time.reservations ??
                    []) as DateReservation[];
                  const isAlreadyReserved = existingReservations.some(
                    (r: DateReservation) => r.date === reservationDateStr
                  );

                  if (!isAlreadyReserved) {
                    reservation.times[i] = {
                      ...time,
                      reservations: [
                        ...existingReservations,
                        { date: reservationDateStr },
                      ],
                    };
                  }
                }
              }
            } else {
              // Old structure: backward compatibility
              if (selectedTime.dateReserved === reservationDateStr) {
                throw new ConflictError(
                  "Reservation already exists for selected time"
                );
              }

              // Mark overlapping time slots as reserved
              const selectedStart = selectedTime.start;
              const selectedEnd = selectedTime.end;

              for (let i = 0; i < reservation.times.length; i++) {
                const time = reservation.times[i];

                // For multiday, only mark overlapping times of the same type
                if (isMultiday && time.type !== selectedTime.type) {
                  continue;
                }

                const timeStart = time.start;
                const timeEnd = time.end;

                // Check if the time range overlaps
                if (timeStart < selectedEnd && timeEnd > selectedStart) {
                  reservation.times[i] = {
                    ...time,
                    dateReserved: reservationDateStr,
                  };
                }
              }
            }

            await extActionRef.update({
              reservation: reservation,
            });
          }
          // Handle non-exclusive time slots without capacity (infinite capacity)
          // No database update needed - users can book any time infinitely
        }
        // Handle simple capacity-based reservations (no time slots)
        else if (reservation.capacity !== undefined) {
          if (body.selectedNumber == null) {
            throw new HttpError(400, "Missing selected number");
          }

          // Get reservation date
          const reservationDate = new Date();
          if (reservation.type === "tomorrow") {
            reservationDate.setDate(reservationDate.getDate() + 1);
          }
          const reservationDateStr = reservationDate
            .toLocaleDateString("sk-SK")
            .replace(/\s/g, "");

          // Reset capacity if date changed
          const currentFreeCapacity =
            reservation.dateReserved === reservationDateStr
              ? reservation.freeCapacity
              : reservation.capacity;

          if (currentFreeCapacity < body.selectedNumber) {
            throw new ConflictError("Not enough capacity available");
          }

          await extActionRef.update({
            reservation: {
              ...reservation,
              dateReserved: reservationDateStr,
              freeCapacity: currentFreeCapacity - body.selectedNumber,
            },
          });
        }
      }

      const data: Record<string, unknown> = {
        dateTime: new Date(),
        checkpoint: cpRef,
        type: "order",
        inputs: body.inputs,
        template: extActionRef,
        state: "todo",
        note: body.note,
      };

      if (isPhoneValid) {
        data.phone = body.phone;
      }
      if (isEmailValid) {
        data.email = body.email;
      }

      // Add action
      const newAction = await buildingRef
        .collection("externalUserActions")
        .add(data);

      logger.info("New external user order:", newAction.id);

      let guestRef;
      // Save guest data if required
      if (actionData?.options?.saveUser) {
        const guestTags: string[] = buildingSnap.data()?.guestTags ?? [];
        const externalTag = "external";
        // if guest tags doesn't contain "external", add it
        if (!guestTags.includes(externalTag)) {
          guestTags.push("external");
          await buildingRef.update({ guestTags });
        }

        const guestData: Record<string, unknown> = {
          isExternal: true,
          tags: [externalTag],
        };
        if (body.email) guestData.email = body.email;
        if (body.phone) guestData.phone = body.phone;
        if (body.note) guestData.name = body.note;

        // Only save if at least one guest field is present
        if (Object.keys(guestData).length > 1) {
          let existingGuest = null;

          // Check for existing guest by email or phone
          if (body.email) {
            const emailQuery = buildingRef
              .collection("guests")
              .where("email", "==", body.email)
              .limit(1);
            const emailQuerySnap = await emailQuery.get();
            if (!emailQuerySnap.empty) {
              existingGuest = emailQuerySnap.docs[0];
            }
          }
          if (!existingGuest && body.phone) {
            const phoneQuery = buildingRef
              .collection("guests")
              .where("phone", "==", body.phone)
              .limit(1);
            const phoneQuerySnap = await phoneQuery.get();
            if (!phoneQuerySnap.empty) {
              existingGuest = phoneQuerySnap.docs[0];
            }
          }

          const now = new Date();
          if (existingGuest) {
            // Update existing guest
            guestData.updatedAt = now;
            guestRef = existingGuest.ref;
            await guestRef.update(guestData);
            logger.info("Updated existing guest:", existingGuest.id);
          } else {
            // Create new guest
            guestData.createdAt = now;
            guestRef = await buildingRef.collection("guests").add(guestData);
            logger.info("New guest data added:", guestRef.id);
          }

          // Add guest reference to action
          await newAction.update({ guest: guestRef });
        }
      }

      // Track 'submit' event in session
      if (sessionID) {
        await SessionRepository.addEvent(body.buildingId, sessionID, {
          type: SessionEventType.SUBMIT,
          action: extActionRef,
          createdOccurrence: newAction,
          dateTime: new Date(),
        });

        // Add guest to session if guest was created
        if (guestRef) {
          await SessionRepository.addGuest(
            body.buildingId,
            sessionID,
            guestRef
          );
        }
      }

      response
        .status(201)
        .send({ message: "Order created", data: newAction.id });
    } catch (error) {
      handleAPIError(error, response);
    }
  }
);

