import { getFirestore } from "firebase-admin/firestore";
import { firestore } from "firebase-admin";
import { z } from "zod";
import { wrapHttpFunction } from "@sentry/google-cloud-serverless";
import {
  onRequest,
  type HttpsOptions,
  type Request,
} from "firebase-functions/v2/https";
import type * as express from "express";

const db = getFirestore();

import DocumentReference = firestore.DocumentReference;
import DocumentData = firestore.DocumentData;
import { region, collectionNames } from "@ofrules/checkpoint-ts-common";

const cors = [
  "http://localhost:3000",
  "http://localhost:4173",
  "https://checkpoint-ext-feedback.web.app",
  "https://checkpoint-ext-feedback.firebaseapp.com",
  "https://checkpoint-webadmin-test.web.app",
  "https://checkpoint-webadmin-test.firebaseapp.com/",
  "https://checkpoint-webadmin.web.app",
  "https://checkpoint-webadmin.firebaseapp.com/",
  "https://checkpoint.ofrules.com/",
  "https://guest.ofrules.com/",
  "https://*.ofrules.com/",
];

export const options = {
  region,
  cors,
};

/**
 * Helper method for getting serviceID
 * @param {DocumentReference} buildingRef
 * @param {string} serviceType
 * @return {string} service ID
 */
export async function getServiceIDByType(
  buildingRef: DocumentReference,
  serviceType: string
): Promise<undefined | DocumentReference<DocumentData>> {
  const serviceSnaps = await db
    .collection(collectionNames.servicesCN)
    .where("building", "==", buildingRef)
    .get();
  const service = serviceSnaps.docs.find(
    (snap) => snap.data().type == serviceType
  );

  return service?.ref;
}

export const baseActionSchema = z.object({
  buildingId: z.string(),
  checkpointId: z.string(),
  extActionPath: z.string(),
});

export const emailRegex =
  /^(([^<>()\\[\].,;:\s@"]+(\.[^<>()\\[\].,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;

export interface IDAndName {
  id: string;
  name: string;
}

/**
 * Wraps an onRequest handler with Sentry tracing.
 * Creates a root span per invocation so performance traces appear in Sentry.
 */
export function onRequestWithSentry(
  opts: HttpsOptions,
  handler: (request: Request, response: express.Response) => void | Promise<void>
) {
  return onRequest(opts, wrapHttpFunction(handler));
}

