   306→            .replace(/\s/g, "");
   307→
   308→          // Reset capacity if date changed
   309→          const currentFreeCapacity =
   310→            reservation.dateReserved === reservationDateStr
   311→              ? reservation.freeCapacity
   312→              : reservation.capacity;
   313→
   314→          if (currentFreeCapacity < body.selectedNumber) {
   315→            throw new ConflictError("Not enough capacity available");
   316→          }
   317→
   318→          await extActionRef.update({
   319→            reservation: {
   320→              ...reservation,
   321→              dateReserved: reservationDateStr,
   322→              freeCapacity: currentFreeCapacity - body.selectedNumber,
   323→            },
   324→          });
   325→        }
   326→      }
   327→
   328→      const data: Record<string, unknown> = {
   329→        dateTime: new Date(),
   330→        checkpoint: cpRef,
   331→        type: "order",
   332→        inputs: body.inputs,
   333→        template: extActionRef,
   334→        state: "todo",
   335→        note: body.note,
   336→      };
   337→
   338→      if (isPhoneValid) {
   339→        data.phone = body.phone;
   340→      }
   341→      if (isEmailValid) {
   342→        data.email = body.email;
   343→      }
   344→
   345→      // Add action
   346→      const newAction = await buildingRef
   347→        .collection("externalUserActions")
   348→        .add(data);
   349→
   350→      logger.info("New external user order:", newAction.id);
   351→
   352→      let guestRef;
   353→      // Save guest data if required
   354→      if (actionData?.options?.saveUser) {
   355→        const guestTags: string[] = buildingSnap.data()?.guestTags ?? [];
   356→        const externalTag = "external";
   357→        // if guest tags doesn't contain "external", add it
   358→        if (!guestTags.includes(externalTag)) {
   359→          guestTags.push("external");
   360→          await buildingRef.update({ guestTags });
   361→        }
   362→
   363→        const guestData: Record<string, unknown> = {
   364→          isExternal: true,
   365→          tags: [externalTag],
   366→        };
   367→        if (body.email) guestData.email = body.email;
   368→        if (body.phone) guestData.phone = body.phone;
   369→        if (body.note) guestData.name = body.note;
   370→
   371→        // Only save if at least one guest field is present
   372→        if (Object.keys(guestData).length > 1) {
   373→          let existingGuest = null;
   374→
   375→          // Check for existing guest by email or phone
   376→          if (body.email) {
   377→            const emailQuery = buildingRef
   378→              .collection("guests")
   379→              .where("email", "==", body.email)
   380→              .limit(1);
   381→            const emailQuerySnap = await emailQuery.get();
   382→            if (!emailQuerySnap.empty) {
   383→              existingGuest = emailQuerySnap.docs[0];
   384→            }
   385→          }
   386→          if (!existingGuest && body.phone) {
   387→            const phoneQuery = buildingRef
   388→              .collection("guests")
   389→              .where("phone", "==", body.phone)
   390→              .limit(1);
   391→            const phoneQuerySnap = await phoneQuery.get();
   392→            if (!phoneQuerySnap.empty) {
   393→              existingGuest = phoneQuerySnap.docs[0];
   394→            }
   395→          }
   396→
   397→          const now = new Date();
   398→          if (existingGuest) {
   399→            // Update existing guest
   400→            guestData.updatedAt = now;
   401→            guestRef = existingGuest.ref;
   402→            await guestRef.update(guestData);
   403→            logger.info("Updated existing guest:", existingGuest.id);
   404→          } else {
   405→            // Create new guest
   406→            guestData.createdAt = now;
   407→            guestRef = await buildingRef.collection("guests").add(guestData);
   408→            logger.info("New guest data added:", guestRef.id);
   409→          }
   410→
   411→          // Add guest reference to action
   412→          await newAction.update({ guest: guestRef });
   413→        }
   414→      }
   415→
   416→      // Track 'submit' event in session
   417→      if (sessionID) {
   418→        await SessionRepository.addEvent(body.buildingId, sessionID, {
   419→          type: SessionEventType.SUBMIT,
   420→          action: extActionRef,
   421→          createdOccurrence: newAction,
   422→          dateTime: new Date(),
   423→        });
   424→
   425→        // Add guest to session if guest was created
   426→        if (guestRef) {
   427→          await SessionRepository.addGuest(
   428→            body.buildingId,
   429→            sessionID,
   430→            guestRef
   431→          );
   432→        }
   433→      }
   434→
   435→      response
   436→        .status(201)
   437→        .send({ message: "Order created", data: newAction.id });
   438→    } catch (error) {
   439→      handleAPIError(error, response);
   440→    }
   441→  }
