     8→import { SessionEventType } from "../session/sessionSchemas";
     9→import {
    10→  BodyValidationError,
    11→  NotFoundError,
    12→  InternalServerError,
    13→} from "../../errorHandling/errors";
    14→import { handleAPIError } from "../../errorHandling/errorHandler";
    15→
    16→const db = getFirestore();
    17→
    18→export const createExternalUserOccurrence = onRequest(
    19→  options,
    20→  async (request, response) => {
    21→    try {
    22→      logger.info("Create external occurrence called");
    23→
    24→      const bodyValidation = baseActionSchema.safeParse(request.body);
    25→      if (!bodyValidation.success) {
    26→        throw new BodyValidationError(bodyValidation.error);
    27→      }
    28→
    29→      const body = bodyValidation.data;
    30→
    31→      // Handle session management
    32→      const { sessionID } = await handleSession(
    33→        request,
    34→        response,
    35→        body.buildingId
    36→      );
    37→
    38→      const buildingRef = db.collection("Buildings").doc(body.buildingId);
    39→
    40→      // Check if building exists and get its language
    41→      const buildingSnap = await buildingRef.get();
    42→
    43→      if (!buildingSnap.exists) {
    44→        logger.debug(`Building (${body.buildingId}) not found`);
    45→        throw new NotFoundError("Building", body.buildingId);
    46→      }
    47→      const buildingLanguage = buildingSnap.data()?.language ?? "cz";
    48→
    49→      const extActionRef = db.doc(body.extActionPath);
    50→
    51→      const snap = await extActionRef.get();
    52→      if (!snap.exists) {
    53→        logger.debug(`Action (${body.extActionPath}) not found`);
    54→        throw new NotFoundError("Action", body.extActionPath);
    55→      }
    56→
    57→      // Check if action exists in building language and get its title
    58→      const actionTextSnap = await extActionRef
    59→        .collection("languages")
    60→        .doc(buildingLanguage)
    61→        .get();
    62→      if (!actionTextSnap.exists) {
    63→        logger.debug(`Action (${body.extActionPath}) text not found`);
    64→        throw new NotFoundError("Action text", body.extActionPath);
    65→      }
    66→
    67→      // Get external action
    68→      const extAction = await extActionRef.get();
    69→      const extActionData = extAction.data();
    70→      const extActionInternalName = extActionData?.internalName;
    71→      const extActionServiceType = extActionData?.serviceType;
    72→      const service = await getServiceIDByType(
    73→        buildingRef,
    74→        extActionServiceType
    75→      );
    76→      if (!service) {
    77→        logger.debug(
    78→          `Service with type '${extActionServiceType}' not found in the building ${buildingRef.id}`
    79→        );
    80→        throw new NotFoundError("Service", extActionServiceType);
    81→      }
    82→
    83→      const cpRef = buildingRef
    84→        .collection("checkpoints")
    85→        .doc(body.checkpointId);
    86→      const cpSnap = await cpRef.get();
    87→      if (!cpSnap.exists) {
    88→        logger.debug(`Action (${body.extActionPath}) text not found`);
    89→        throw new NotFoundError("Checkpoint", body.checkpointId);
    90→      }
    91→
    92→      // Check if we have some ongoing tasks before adding occurrence
    93→      const ongoingActionsSnaps = await cpRef
    94→        .collection("occurrences")
    95→        .where("template", "==", extActionRef)
    96→        .where("state", "!=", "done")
    97→        .get();
    98→
    99→      if (!ongoingActionsSnaps.empty) {
   100→        logger.debug("Ongoing Occurrence, not creating another one");
   101→        response.status(200).send({ message: "Ongoing occurrence exists" });
   102→
   103→        return;
   104→      }
   105→
   106→      const batch = db.batch();
   107→
   108→      // same date for all entities
   109→      const dateTime = new Date();
   110→
   111→      const newOccurrenceRef = cpRef.collection("occurrences").doc();
   112→      // Create new occurrence
   113→      batch.set(newOccurrenceRef, {
   114→        dateTime,
   115→        name: extActionInternalName,
   116→        template: extActionRef,
   117→        service: service,
   118→        state: "todo",
   119→      });
   120→
   121→      // Change checkpoint state to "task" only if's not in "error" state
   122→      if (cpSnap.data()?.state !== "error") {
   123→        await cpRef.update({ state: "task" });
   124→      }
   125→
   126→      // Add action to the new occurrence
   127→      batch.create(newOccurrenceRef.collection("actions").doc(), {
   128→        dateTime,
   129→        type: "created",
   130→      });
   131→
   132→      // also add external user action
   133→      const externalUserActionRef = buildingRef
   134→        .collection("externalUserActions")
   135→        .doc();
   136→      batch.create(externalUserActionRef, {
   137→        dateTime,
   138→        checkpoint: cpRef,
   139→        occurrence: newOccurrenceRef,
   140→        template: extActionRef,
   141→        type: "occurrence",
   142→      });
   143→
   144→      await batch.commit();
   145→
   146→      const newOccurrence = await newOccurrenceRef.get();
   147→      if (!newOccurrence.exists) {
   148→        logger.info("Occurrence not created");
   149→        throw new InternalServerError("Error creating occurrence");
   150→      }
   151→
   152→      logger.info("New occurrence ID:", newOccurrenceRef.id);
   153→
   154→      // Track 'submit' event in session
   155→      if (sessionID) {
   156→        await SessionRepository.addEvent(body.buildingId, sessionID, {
   157→          type: SessionEventType.SUBMIT,
   158→          action: extActionRef,
   159→          createdOccurrence: externalUserActionRef,
   160→          dateTime,
   161→        });
   162→      }
   163→
   164→      response
   165→        .status(201)
   166→        .send({ message: "Occurrence created", data: newOccurrenceRef.id });
   167→    } catch (error) {
   168→      handleAPIError(error, response);
   169→    }
   170→  }
   171→);
