    12→
    13→export const checkCheckpointNFC = onRequest(
    14→  options,
    15→  async (request, response) => {
    16→    try {
    17→      await verifyAuthenticated(request);
    18→    } catch (error) {
    19→      if (error instanceof UnauthorizedError) {
    20→        response.status(401).send("Unauthorized");
    21→      }
    22→
    23→      response.status(500);
    24→
    25→      return;
    26→    }
    27→
    28→    logger.info("Check Checkpoint NFC called");
    29→
    30→    const questionOrderSchema = z.object({
    31→      buildingID: z.string(),
    32→      checkpointName: z.string(),
    33→    });
    34→
    35→    const bodyValidation = questionOrderSchema.safeParse(request.body);
    36→    if (!bodyValidation.success) {
    37→      response.status(400).send(bodyValidation.error);
    38→
    39→      return;
    40→    }
