    42→    const body = bodyValidation.data;
    43→
    44→    // Handle session management
    45→    await handleSession(request, response, body.buildingID);
    46→    const buildingRef = db
    47→      .collection(collectionNames.buildingsCN)
    48→      .doc(body.buildingID);
    49→    const cpSnaps = await buildingRef
    50→      .collection(collectionNames.checkpointsCN)
    51→      .get();
    52→
    53→    const filteredCps = cpSnaps.docs.filter((doc) =>
    54→      (doc.data().name as string)
    55→        .toLowerCase()
    56→        .includes(body.checkpointName.toLowerCase())
    57→    );
