    19→const storage = getStorage();
    20→const bucketName = "checkpoint-west3"; // Defined bucket name
    21→const publicGuestPortalPath = "guest-portal/public";
    22→
    23→export const reuploadImages = onRequest(
    24→  {
    25→    cors: true,
    26→    region: REGION,
    27→  },
    28→  endpointWrapper(
    29→    buildingIDQuerySchema,
    30→    reuploadImagesSchema,
    31→    reuploadImagesResponseSchema,
    32→    async (query, body) => {
    33→      logger.info(
    34→        `Reuploading ${body.images.length} image(s) for building '${query.buildingID}'`
    35→      );
    36→
    37→      // Verify building exists
    38→      await BuildingRepository.getByID(query.buildingID);
    39→
    40→      const CONCURRENCY_LIMIT = 10;
    41→      const uploadedImageResults: { url: string; name: string }[] = [];
    42→      const imageChunks: (typeof body.images)[] = [];
    43→
    44→      for (let i = 0; i < body.images.length; i += CONCURRENCY_LIMIT) {
    45→        imageChunks.push(body.images.slice(i, i + CONCURRENCY_LIMIT));
    46→      }
    47→
    48→      for (const chunk of imageChunks) {
    49→        const uploadPromises = chunk.map(async (image) => {
    50→          const urlObj = new URL(image.url);
    51→          const pathSegments = urlObj.pathname.split("/");
    52→          const originalFileName = pathSegments[pathSegments.length - 1];
    53→
    54→          let fileName = image.name;
    55→          if (fileName) {
    56→            // If a name is provided, check for an extension
    57→            if (!extname(fileName) && originalFileName) {
    58→              const originalExtension = extname(originalFileName);
    59→              fileName += originalExtension;
    60→            }
    61→          } else {
    62→            // If no name is provided, use the original file name from the URL
    63→            fileName = originalFileName || `image-${Date.now()}`;
    64→          }
    65→
    66→          const destinationPath = `${publicGuestPortalPath}/${query.buildingID}/${fileName}`;
    67→          const fileRef = storage.bucket(bucketName).file(destinationPath);
    68→
    69→          try {
    70→            // Fetch the image stream
    71→            const response = await fetch(image.url);
    72→            if (!response.ok) {
    73→              throw new HttpError(
    74→                response.status,
    75→                `Failed to fetch image from ${image.url}: ${response.statusText}`
    76→              );
    77→            }
    78→
    79→            // Upload the image stream to Firebase Storage
    80→            await new Promise<void>((resolve, reject) => {
    81→              const uploadStream = fileRef.createWriteStream({
    82→                metadata: {
    83→                  contentType:
    84→                    response.headers.get("content-type") ??
    85→                    "application/octet-stream",
    86→                },
    87→              });
    88→
    89→              uploadStream.on("error", (err) => {
    90→                logger.error(`Failed to upload image ${fileName}:`, err);
    91→                reject(
    92→                  new HttpError(500, `Failed to upload image ${fileName}`)
    93→                );
    94→              });
    95→
    96→              uploadStream.on("finish", () => {
    97→                logger.info(`Successfully uploaded image: ${destinationPath}`);
    98→                resolve();
    99→              });
   100→
   101→              if (response.body) {
   102→                const nodeReadable = Readable.fromWeb(response.body as any);
   103→                nodeReadable.pipe(uploadStream);
   104→              } else {
   105→                reject(
   106→                  new HttpError(500, `No body received for image ${image.url}`)
   107→                );
   108→              }
   109→            });
   110→
   111→            const publicUrl = `https://firebasestorage.googleapis.com/v0/b/${bucketName}/o/${encodeURIComponent(destinationPath)}?alt=media`;
   112→
   113→            return { url: publicUrl, name: fileName };
   114→          } catch (error) {
   115→            logger.error(`Error processing image ${image.url}:`, error);
   116→            throw error;
   117→          }
   118→        });
   119→
   120→        const chunkResults = await Promise.all(uploadPromises);
   121→        uploadedImageResults.push(...chunkResults);
   122→      }
   123→
   124→      return {
   125→        status: 201,
   126→        body: {
   127→          message: "Images reuploaded successfully",
   128→          data: uploadedImageResults,
   129→        },
   130→      };
   131→    },
   132→    { auth: verifySuperadmin }
   133→  )
   134→);
