    30→
    31→      const data = bodyValidation.data;
    32→      const now = Date.now();
    33→
    34→      let notificationConfig: Pick<
    35→        IGuestNotificationConfiguration,
    36→        | "name"
    37→        | "description"
    38→        | "title"
    39→        | "message"
    40→        | "type"
    41→        | "recurrence"
    42→        | "templateID"
    43→      >;
    44→
    45→      // If templateID is provided, load template and use its configuration
    46→      if (data.templateID) {
    47→        // This will throw NotFoundError if template doesn't exist
    48→        const template = await TemplateRepository.getByID(data.templateID);
    49→
    50→        // Use template config, but allow overrides from request
    51→        const type = data.type ?? template.type;
    52→        const recurrence = (data.recurrence ??
    53→          template.recurrence) as IRecurrenceConfig;
    54→        notificationConfig = {
    55→          name: data.name ?? template.name,
    56→          description: data.description ?? template.description,
    57→          title: data.title ?? template.title,
