    68→          name: data.name!,
    69→          description: data.description!,
    70→          title: data.title!,
    71→          message: data.message!,
    72→          type: type,
    73→          recurrence,
    74→          templateID: null,
    75→        };
    76→      }
    77→
    78→      let nextScheduledAt: Date | null = null;
    79→
    80→      if (notificationConfig.type !== NotificationType.DELAYED) {
