    19→export const updateNotification = onRequest(
    20→  { cors: true, region: REGION },
    21→  async (request, response) => {
    22→    try {
    23→      await verifyAuthenticated(request);
    24→
    25→      logger.info("Update notification called");
    26→
    27→      // Validate query parameters
    28→      const paramsResult = validateRequiredQueryParams({
    29→        buildingID: request.query.buildingID,
    30→        notificationId: request.query.notificationId,
    31→      });
    32→
    33→      if (!paramsResult.success) {
    34→        throw new QueryValidationError(paramsResult.error);
    35→      }
    36→
    37→      const { buildingID, notificationId } = paramsResult.values;
    38→
    39→      // Validate request body
    40→      const bodyValidation = updateNotificationSchema.safeParse(request.body);
    41→      if (!bodyValidation.success) {
    42→        throw new BodyValidationError(bodyValidation.error);
    43→      }
    44→
    45→      const updates = bodyValidation.data;
    46→
    47→      // Get existing notification - will throw NotFoundError if it doesn't exist
    48→      const notification = await NotificationRepository.getByID(
    49→        buildingID,
    50→        notificationId
    51→      );
    52→
    53→      // Build update object - exclude id and buildingID as they cannot be changed
    54→      const updateData: Partial<
    55→        Omit<IGuestNotificationConfiguration, "id" | "buildingID">
    56→      > = {};
    57→
    58→      if (updates.name !== undefined) updateData.name = updates.name;
    59→      if (updates.description !== undefined)
    60→        updateData.description = updates.description;
    61→      if (updates.title !== undefined) updateData.title = updates.title;
    62→      if (updates.message !== undefined) updateData.message = updates.message;
    63→      if (updates.enabled !== undefined) updateData.enabled = updates.enabled;
    64→
    65→      if (updates.type !== undefined) {
    66→        updateData.type = updates.type;
    67→      }
    68→
    69→      if (updates.recurrence !== undefined) {
    70→        const recurrence = updates.recurrence as any as IRecurrenceConfig;
    71→        // Convert endDate string to Date if present
    72→        const processedRecurrence: any = { ...recurrence };
    73→        if ("endDate" in recurrence && recurrence.endDate) {
    74→          processedRecurrence.endDate = new Date(recurrence.endDate as any);
    75→        }
    76→        updateData.recurrence = processedRecurrence as IRecurrenceConfig;
    77→      }
    78→
    79→      // Recalculate nextScheduledAt if schedule-related fields changed
    80→      if (updates.type !== undefined || updates.recurrence !== undefined) {
    81→        // Determine the effective type and recurrence
