import { onRequest } from "firebase-functions/v2/https";
import { logger } from "firebase-functions/v2";
import { generateOpenApiDocument } from "./generator";
import { REGION } from "@ofrules/checkpoint-ts-common";

/**
 * Serves OpenAPI specification as JSON
 *
 * @endpoint GET /openapi.json
 * @returns OpenAPI 3.0 specification document
 *
 * @example
 * GET https://us-central1-checkpoint-app.cloudfunctions.net/checkpoint-api/openapi.json
 */
export const openapi = onRequest({ cors: true, region: REGION }, (req, res) => {
  try {
    logger.info("OpenAPI JSON requested");
    const document = generateOpenApiDocument();
    res.setHeader("Content-Type", "application/json");
    res.status(200).send(document);
  } catch (error) {
    logger.error("Error generating OpenAPI document:", error);
    res.status(500).send({ error: "Failed to generate OpenAPI document" });
  }
});

/**
 * Serves Swagger UI for interactive API documentation
 *
 * @endpoint GET /docs
 * @returns HTML page with Swagger UI
 *
 * @example
 * GET https://us-central1-checkpoint-app.cloudfunctions.net/checkpoint-api/docs
 */
export const docs = onRequest({ cors: true, region: REGION }, (req, res) => {
  try {
    logger.info("API documentation requested");
    const document = generateOpenApiDocument();

    // Serve Swagger UI HTML
    const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Checkpoint API Documentation</title>
  <link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/swagger-ui.css" />
  <link rel="icon" type="image/png" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/favicon-32x32.png" sizes="32x32" />
  <link rel="icon" type="image/png" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/favicon-16x16.png" sizes="16x16" />
  <style>
    body {
      margin: 0;
      padding: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    }
    .swagger-ui .topbar {
      background-color: #2c3e50;
    }
    .swagger-ui .info .title {
      color: #2c3e50;
    }
  </style>
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/swagger-ui-bundle.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5/swagger-ui-standalone-preset.js"></script>
  <script>
    window.onload = function() {
      window.ui = SwaggerUIBundle({
        spec: ${JSON.stringify(document)},
        dom_id: '#swagger-ui',
        deepLinking: true,
        presets: [
          SwaggerUIBundle.presets.apis,
          SwaggerUIStandalonePreset
        ],
        plugins: [
          SwaggerUIBundle.plugins.DownloadUrl
        ],
        layout: "StandaloneLayout",
        defaultModelsExpandDepth: 1,
        defaultModelExpandDepth: 1,
        docExpansion: "list",
        filter: true,
        showRequestHeaders: true,
        tryItOutEnabled: true
      });
    };
  </script>
</body>
</html>
    `;

    res.setHeader("Content-Type", "text/html");
    res.status(200).send(html);
  } catch (error) {
    logger.error("Error serving API documentation:", error);
    res.status(500).send(`
      <!DOCTYPE html>
      <html>
      <head><title>Error</title></head>
      <body>
        <h1>Error</h1>
        <p>Failed to generate API documentation. Please check server logs.</p>
      </body>
      </html>
    `);
  }
});

