    21→  "image/jpeg",
    22→  "image/jpg",
    23→  "image/png",
    24→  "image/webp",
    25→  "image/gif",
    26→  "image/bmp",
    27→  "image/tiff",
    28→];
    29→const SUPPORTED_IMAGE_EXTENSIONS = new Set([
    30→  ".jpg",
    31→  ".jpeg",
    32→  ".png",
    33→  ".webp",
    34→  ".gif",
    35→  ".bmp",
    36→  ".tiff",
