    59→/**
    60→ * Generates thumbnails for images and videos uploaded to Firebase Storage.
    61→ * Triggers on file upload to: app/private/buildings/{buildingId}/occurrences/{occurrenceId}/{id}_{filename}
    62→ * Saves thumbnails to the same directory as the original file, with a `_200x200` suffix added
    63→ * before the extension (e.g. `myimage_200x200.jpg`). Videos produce a `_200x200.jpg` still frame.
    64→ */
    65→export async function generateThumbnailsHandler(
    66→  event: StorageEvent
    67→): Promise<null> {
    68→  const filePath = event.data.name;
    69→
    70→  // Guard against missing file name (valid in the Storage event type but would crash below)
    71→  if (!filePath) return null;
    72→
    73→  // Silently ignore thumbnails and any file outside the known permanent paths
    74→  // (occurrence attachments or guest-action attachments). Staging uploads and
    75→  // unrelated bucket objects are skipped without logging.
    76→  const pathPattern =
    77→    /^app\/private\/buildings\/[^/]+\/(occurrences|guestActions)\/[^/]+\/[^/]+$/;
    78→  if (
    79→    filePath.includes(`_${THUMBNAIL_SIZE}x${THUMBNAIL_SIZE}`) ||
    80→    !pathPattern.test(filePath)
    81→  ) {
    82→    return null;
    83→  }
    84→
    85→  const contentType = event.data.contentType;
    86→
    87→  functions.logger.info("Processing file", { filePath, contentType });
    88→
    89→  // Check if file type is supported. Some clients (e.g. Android) upload files
    90→  // with a generic "application/octet-stream" content type, so fall back to
    91→  // the file extension when the MIME type is not a recognised image/video type.
    92→  const ext = path.extname(filePath).toLowerCase();
    93→  const isImage =
    94→    (contentType && SUPPORTED_IMAGE_TYPES.includes(contentType)) ??
    95→    SUPPORTED_IMAGE_EXTENSIONS.has(ext);
    96→  const isVideo =
    97→    !isImage &&
    98→    ((contentType && SUPPORTED_VIDEO_TYPES.includes(contentType)) ??
    99→      SUPPORTED_VIDEO_EXTENSIONS.has(ext));
   100→  const isPdf =
   101→    !isImage &&
   102→    !isVideo &&
   103→    ((contentType && SUPPORTED_PDF_TYPES.includes(contentType)) ??
   104→      SUPPORTED_PDF_EXTENSIONS.has(ext));
   105→
   106→  if (!isImage && !isVideo && !isPdf) {
   107→    functions.logger.info("Unsupported file type, skipping");
   108→
   109→    return null;
   110→  }
   111→
   112→  // Read action metadata from the Storage event — set by moveAttachments when
   113→  // copying the file to its permanent location. No extra getMetadata() call needed.
   114→  const customMetadata = event.data.metadata as
   115→    | Record<string, string>
   116→    | undefined;
   117→  const actionID = customMetadata?.actionID;
   118→
   119→  // Parse path parts: app/private/buildings/{buildingID}/{entityType}/{entityID}/{id}_{filename}
   120→  const pathParts = filePath.split("/");
   121→  const buildingID = pathParts[3];
   122→  const entityType = pathParts[4]; // "occurrences" | "guestActions"
   123→  const entityID = pathParts[5];
   124→  const fileSegment = pathParts[6];
   125→  const fileId = fileSegment.substring(0, fileSegment.indexOf("_"));
   126→
   127→  // Resolve the Firestore action reference based on entity type.
   128→  const db = getFirestore();
   129→  let actionRef: FirebaseFirestore.DocumentReference;
   130→
   131→  if (entityType === "guestActions") {
   132→    const guestActionID = customMetadata?.guestActionID;
   133→    if (!guestActionID || !actionID) {
   134→      functions.logger.info(
   135→        "No guest action metadata on file, skipping Firestore update",
   136→        { filePath }
   137→      );
   138→
   139→      return null;
   140→    }
   141→    actionRef = db
   142→      .collection(collectionNames.buildingsCN)
   143→      .doc(buildingID)
   144→      .collection(collectionNames.externalUserActionsCN)
   145→      .doc(guestActionID)
   146→      .collection(collectionNames.actionsCN)
   147→      .doc(actionID);
   148→  } else {
   149→    // occurrences
   150→    const checkpointID = customMetadata?.checkpointID;
   151→    if (!checkpointID || !actionID) {
   152→      functions.logger.info(
   153→        "No action metadata on file, skipping Firestore update",
   154→        { filePath }
   155→      );
   156→
   157→      return null;
   158→    }
   159→    actionRef = db
   160→      .collection(collectionNames.buildingsCN)
   161→      .doc(buildingID)
   162→      .collection(collectionNames.checkpointsCN)
   163→      .doc(checkpointID)
   164→      .collection(collectionNames.occurrencesCN)
   165→      .doc(entityID)
   166→      .collection(collectionNames.actionsCN)
   167→      .doc(actionID);
   168→  }
   169→
   170→  const actionSnap = await actionRef.get();
   171→  if (!actionSnap.exists) {
   172→    functions.logger.info("Action not found, skipping thumbnail generation", {
   173→      buildingID,
   174→      entityType,
   175→      entityID,
   176→      actionID,
   177→    });
   178→
   179→    return null;
   180→  }
   181→
   182→  const bucket = admin.storage().bucket(event.data.bucket);
   183→  const fileName = path.basename(filePath);
   184→  const tempFilePath = path.join(os.tmpdir(), fileName);
   185→
   186→  try {
   187→    // Download file to temp directory
   188→    functions.logger.info("Downloading file to temp directory");
   189→    await bucket.file(filePath).download({ destination: tempFilePath });
   190→
   191→    let thumbnailBuffer: Buffer;
   192→
   193→    if (isImage) {
   194→      functions.logger.info("Processing image");
   195→      thumbnailBuffer = await sharp(tempFilePath)
   196→        .resize(THUMBNAIL_SIZE, THUMBNAIL_SIZE, {
   197→          fit: "cover",
   198→          position: "center",
   199→        })
   200→        .jpeg({ quality: 85 })
   201→        .toBuffer();
   202→    } else if (isPdf) {
   203→      functions.logger.info("Processing PDF");
   204→      thumbnailBuffer = await extractPdfThumbnail(tempFilePath);
   205→    } else {
   206→      // isVideo
   207→      functions.logger.info("Processing video");
   208→      thumbnailBuffer = await extractVideoFrame(tempFilePath);
   209→    }
   210→
   211→    // Thumbnail path: same directory as the original, with `_200x200` appended before the extension.
   212→    // For image.jpg -> image_200x200.jpg
   213→    // For video.mp4 -> video_200x200.jpg (JPEG still frame)
   214→    const fileExt = path.extname(fileName);
   215→    const nameWithoutExt = path.basename(fileName, fileExt);
   216→    const thumbnailFileName = `${nameWithoutExt}_${THUMBNAIL_SIZE}x${THUMBNAIL_SIZE}.jpg`;
   217→    const thumbnailPath = path.join(path.dirname(filePath), thumbnailFileName);
   218→
   219→    functions.logger.info("Uploading thumbnail", {
   220→      path: thumbnailPath,
   221→    });
   222→
   223→    // Upload thumbnail
   224→    const thumbnailFile = bucket.file(thumbnailPath);
   225→    await thumbnailFile.save(thumbnailBuffer, {
   226→      metadata: {
   227→        contentType: "image/jpeg",
   228→        metadata: {
   229→          originalFile: filePath,
   230→        },
   231→      },
   232→    });
   233→
   234→    functions.logger.info("Thumbnail generated successfully");
   235→
   236→    // Update the action document with the thumbnail path.
   237→    // Re-use the already-fetched actionSnap data to avoid an extra read.
   238→    const files = (actionSnap.data()?.files ?? []) as ActionFile[];
   239→    const updatedFiles = files.map((f) =>
   240→      f.id === fileId ? { ...f, thumbnailPath } : f
   241→    );
   242→
   243→    await actionRef.update({ files: updatedFiles });
   244→
   245→    functions.logger.info("Updated action with thumbnail path", {
   246→      actionID,
   247→      fileId,
   248→      thumbnailPath,
   249→    });
   250→
   251→    return null;
   252→  } catch (error) {
   253→    functions.logger.error("Error generating thumbnail:", error);
   254→    throw error;
   255→  } finally {
   256→    // Clean up temp file
   257→    try {
   258→      await fs.unlink(tempFilePath);
   259→    } catch (error) {
   260→      functions.logger.warn("Error cleaning up temp file:", error);
   261→    }
   262→  }
   263→}
