   265→/**
   266→ * Renders the first page of a PDF file and returns a JPEG thumbnail buffer.
   267→ */
   268→async function extractPdfThumbnail(filePath: string): Promise<Buffer> {
   269→  const data = new Uint8Array(await fs.readFile(filePath));
   270→
   271→  const pdfDoc = await pdfjs.getDocument({
   272→    data,
   273→    useWorkerFetch: false,
   274→    isEvalSupported: false,
   275→    useSystemFonts: true,
   276→  }).promise;
   277→
   278→  const page = await pdfDoc.getPage(1);
   279→  // Render at scale 1 (72 dpi). A standard A4 page is ~595×842 px — well
   280→  // above the thumbnail size, so downscaling gives good quality.
   281→  const viewport = page.getViewport({ scale: 1 });
   282→
   283→  const canvas = createCanvas(
   284→    Math.round(viewport.width),
   285→    Math.round(viewport.height)
   286→  );
   287→  const context = canvas.getContext("2d");
   288→  await page.render({
   289→    canvasContext: context as unknown as CanvasRenderingContext2D,
   290→    viewport,
   291→  }).promise;
   292→
   293→  return (
   294→    sharp(canvas.toBuffer("image/png"))
   295→      // Strip the typical white margins so the actual content fills the frame.
   296→      .trim({ background: "#ffffff", threshold: 10 })
   297→      // Shrink the content to fit within the square without cropping any of it.
   298→      // White bars are added on the shorter axis to produce a 200×200 image.
   299→      .resize(THUMBNAIL_SIZE, THUMBNAIL_SIZE, {
   300→        fit: "contain",
   301→        background: "#ffffff",
   302→      })
   303→      .jpeg({ quality: 85 })
   304→      .toBuffer()
   305→  );
   306→}
   307→
   308→/**
   309→ * Extracts a frame from a video file and resizes it to thumbnail size
   310→ */
   311→async function extractVideoFrame(videoPath: string): Promise<Buffer> {
   312→  if (!ffmpegPath) {
   313→    throw new Error("ffmpeg-static path not found");
   314→  }
   315→
   316→  const tempFramePath = `${videoPath}_frame.jpg`;
   317→
   318→  try {
   319→    // Extract frame at 1 second using ffmpeg
   320→    await new Promise<void>((resolve, reject) => {
   321→      const ffmpegProcess = spawn(ffmpegPath as string, [
   322→        "-i",
   323→        videoPath,
   324→        "-ss",
   325→        "00:00:01",
   326→        "-vframes",
   327→        "1",
   328→        "-vf",
   329→        `scale=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}:force_original_aspect_ratio=increase,crop=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}`,
   330→        "-q:v",
   331→        "2",
   332→        tempFramePath,
   333→      ]);
   334→
   335→      let errorOutput = "";
   336→
   337→      ffmpegProcess.stderr.on("data", (data: Buffer) => {
   338→        errorOutput += data.toString();
   339→      });
   340→
   341→      ffmpegProcess.on("close", (code: number | null) => {
   342→        if (code === 0) {
   343→          resolve();
   344→        } else {
   345→          reject(
   346→            new Error(`ffmpeg process exited with code ${code}: ${errorOutput}`)
   347→          );
   348→        }
   349→      });
   350→
   351→      ffmpegProcess.on("error", (err: Error) => {
   352→        reject(err);
   353→      });
   354→    });
   355→
   356→    // Read and optimize with sharp
   357→    const thumbnailBuffer = await sharp(tempFramePath)
   358→      .jpeg({ quality: 85 })
   359→      .toBuffer();
   360→
   361→    return thumbnailBuffer;
   362→  } finally {
   363→    // Clean up temp frame file
   364→    try {
   365→      await fs.unlink(tempFramePath);
   366→    } catch (error) {
   367→      functions.logger.warn("Error cleaning up temp frame file:", error);
   368→    }
   369→  }
   370→}
