    52→  const lang = store.chosenLang
    53→  // Convert language codes to display labels
    54→  const labelMap: Record<string, string> = {
    55→    sk: 'SK',
    56→    en: 'ENG',
    57→    cz: 'CZ',
    58→    cs: 'CZ' // Czech alternative code
    59→  }
    60→  return labelMap[lang] || lang.toUpperCase()
    61→})
    62→
    63→const currentLangWifi = computed(() => {
    64→  return store.buildingData?.wifi?.[store.chosenLang]
    65→})
    66→
    67→const handleLanguageClick = () => {
    68→  // Cycle through available languages from store
    69→  const langs = availableLanguages.value
    70→  if (langs.length <= 1) return // Don't cycle if only one language
    71→
    72→  const currentIndex = langs.findIndex((l: string) => l === store.chosenLang)
    73→  const nextIndex = (currentIndex + 1) % langs.length
    74→  const nextLang = langs[nextIndex]
    75→
    76→  store.chosenLang = nextLang
    77→  localStorage.setItem('userLanguage', nextLang)
    78→  emit('languageChange', nextLang)
    79→}
    80→
    81→const handleInfoClick = () => {
    82→  showInfoDialog.value = true
    83→}
    84→
    85→const handleImageClick = () => {
    86→  if (hasWifiTag.value) {
    87→    showWifiPanel.value = !showWifiPanel.value
    88→  }
    89→}
