     5→
     6→export enum ActionType {
     7→  /**
     8→   * First action of every Occurrence
     9→   */
    10→  created = "created",
    11→  workStarted = "workStarted",
    12→  /**
    13→   * Something was not fixed, Occurrence is in state `todo`
    14→   */
    15→  partiallyFixed = "partiallyFixed",
    16→  /**
    17→   * Occurrence fixed, either in state `toCheck`, or `done`, since some Occurrences do not require checking
    18→   */
    19→  completelyFixed = "completelyFixed",
    20→  checkStarted = "checkStarted",
    21→  checkOk = "checkOk",
    22→  checkFailed = "checkFailed",
    23→  comment = "comment",
    24→}
    25→
    26→// Note:
    27→// we use both createdBy and createdAutomatically
    28→// since maybe in the future we will want to know which worker created the action, so we will create robot users
    29→
    30→export interface ActionFile {
    31→  id: string;
    32→  filename: string;
    33→  path: string;
    34→  /**
    35→   * Full storage path to the generated thumbnail. Only present after the thumbnail worker processes the file.
    36→   */
    37→  thumbnailPath?: string;
    38→}
    39→
    40→export interface IAction {
    41→  /**
    42→   * Reference to the user who created the action, can be null if created automatically
    43→   */
    44→  createdBy: DocumentReference | null;
    45→  /**
    46→   * Date of the action creation
    47→   */
    48→  dateTime: Date;
    49→  /**
    50→   * Type of the action
    51→   */
    52→  type: ActionType;
    53→  /**
    54→   * If the action is quick action - only one action in the Occurrence
    55→   */
    56→  quickAction: boolean;
    57→  /**
    58→   * If the action was created by some worker - without the user interaction
    59→   */
    60→  createdAutomatically: boolean;
    61→  /**
    62→   * Action description
    63→   */
    64→  description?: string;
    65→  /**
    66→   * Reference to the action which ends the duration of this action.
    67→   * If null - action is still in progress / last action state
    68→   */
    69→  endAction: DocumentReference | null;
    70→  files?: ActionFile[];
    71→}
    72→
    73→export interface IFirebaseAction extends IAction {
    74→  id?: string;
    75→}
    76→
    77→function newWorkAction(
    78→  type: ActionType,
    79→  createdBy: DocumentReference | null,
    80→  description?: string,
    81→  createdAutomatically = false,
    82→  files?: ActionFile[],
    83→  quickAction = false
    84→): IAction {
    85→  const action: IAction = {
    86→    createdBy,
    87→    dateTime: new Date(),
    88→    type,
    89→    quickAction,
    90→    endAction: null,
    91→    createdAutomatically,
    92→  };
    93→
    94→  if (description) {
    95→    action.description = description;
    96→  }
    97→
    98→  if (files) {
    99→    action.files = files;
   100→  }
   101→
   102→  return action;
   103→}
   104→
   105→export function newCreatedAction(
   106→  createdBy: DocumentReference,
   107→  description?: string,
   108→  files?: ActionFile[]
   109→): IFirebaseAction {
   110→  return newWorkAction(ActionType.created, createdBy, description, false, files);
   111→}
   112→
   113→export function newWorkStartedAction(
   114→  createdBy: DocumentReference,
   115→  description?: string,
   116→  files?: ActionFile[]
   117→): IFirebaseAction {
   118→  return newWorkAction(ActionType.workStarted, createdBy, description, false, files);
   119→}
