   133→): IFirebaseAction {
   134→  return newWorkAction(ActionType.partiallyFixed, createdBy, description, false, files);
   135→}
   136→
   137→export function newCheckOkAction(
   138→  createdBy: DocumentReference,
   139→  description?: string,
   140→  files?: ActionFile[]
   141→): IFirebaseAction {
   142→  return newWorkAction(ActionType.checkOk, createdBy, description, false, files);
   143→}
   144→
   145→export function newCheckFailedAction(
   146→  createdBy: DocumentReference,
   147→  description?: string,
