    29→// Get external feedback action data
    30→export const getExternalUserActionData = onRequestWithSentry(
    31→  options,
    32→  async (request, response) => {
    33→    try {
    34→      logger.info("Get feedback action called");
    35→
    36→      const queryParams: { [k: string]: string } = {};
    37→
    38→      queryParams.extFeedbackId = request.query.extFeedbackId as string;
    39→      queryParams.extActionId = request.query.extActionId as string;
    40→      queryParams.buildingId = request.query.buildingId as string;
    41→      queryParams.checkpointId = request.query.checkpointId as string;
    42→
    43→      if (
    44→        (!queryParams.extFeedbackId && !queryParams.extActionId) ||
    45→        !queryParams.buildingId ||
    46→        !queryParams.checkpointId
    47→      ) {
    48→        throw new QueryValidationError("Missing params");
    49→      }
    50→
    51→      // Handle session management
    52→      const { sessionID } = await handleSession(
    53→        request,
    54→        response,
    55→        queryParams.buildingId
    56→      );
    57→
    58→      // Build refs for parallel fetch
    59→      const buildingRef = db
    60→        .collection("Buildings")
    61→        .doc(queryParams.buildingId);
    62→
    63→      const checkpointRef = db
    64→        .collection("Buildings")
    65→        .doc(queryParams.buildingId)
    66→        .collection("checkpoints")
    67→        .doc(queryParams.checkpointId);
    68→
    69→      const [buildingSnap, checkpointSnap] = await Sentry.startSpan(
    70→        { name: "firestore.getBuildingAndCheckpoint", op: "db.query" },
    71→        () => Promise.all([buildingRef.get(), checkpointRef.get()])
    72→      );
    73→
    74→      if (!buildingSnap.exists) {
    75→        throw new NotFoundError("Building", queryParams.buildingId);
    76→      }
    77→      if (!checkpointSnap.exists) {
    78→        throw new NotFoundError("Checkpoint", queryParams.checkpointId);
    79→      }
    80→
    81→      const building = buildingSnap.data();
    82→      const checkpoint = checkpointSnap.data();
    83→      const checkpointNum = checkpoint?.name?.match(/\d+/g)?.[0];
