    85→      let actionData = undefined as any;
    86→      let actionsDataList = undefined as undefined | any[];
    87→      let viewsDataList = undefined as undefined | any[];
    88→
    89→      const getExtActionData = async (actionRefPath: string) => {
    90→        const extActionRef = db.doc(actionRefPath);
    91→
    92→        const actionSnap = await extActionRef.get();
    93→        if (!actionSnap.exists) {
    94→          throw new NotFoundError("Action", actionRefPath);
    95→        }
    96→
    97→        const actionData = {
    98→          id: actionSnap.id,
    99→          path: actionRefPath,
   100→          ...actionSnap.data(),
   101→        } as any;
   102→
   103→        const actionLangsSnaps = await extActionRef
   104→          .collection("languages")
   105→          .get();
   106→        if (actionLangsSnaps.empty) {
   107→          return actionData;
   108→        }
   109→
   110→        actionData.texts = {} as any;
   111→        for (const actionLang of actionLangsSnaps.docs) {
   112→          const data = actionLang.data();
   113→          actionData.texts[actionLang.id] = buildActionTexts(
   114→            data,
   115→            checkpointNum,
   116→            building?.name
   117→          );
   118→        }
   119→
   120→        return actionData;
   121→      };
   122→
   123→      // Check if it is only one simple action or we have to load all actions
   124→      const isSimpleAction = !queryParams.extFeedbackId;
   125→      if (isSimpleAction) {
   126→        try {
   127→          actionData = await getExtActionData(
   128→            "ext-feedback-action/" + queryParams.extActionId
   129→          );
   130→        } catch {
   131→          actionData = await getExtActionData(
   132→            `Buildings/${queryParams.buildingId}/externalFeedbackActions/${queryParams.extActionId}`
   133→          );
   134→        }
   135→      } else {
   136→        [actionsDataList, viewsDataList] = await Sentry.startSpan(
   137→          { name: "firestore.getActionsAndViews", op: "db.query" },
   138→          async () => {
   139→            const [extActionsSnap, extViewsSnap] = await Promise.all([
   140→              buildingRef.collection("externalFeedbackActions").get(),
   141→              buildingRef.collection("externalFeedbackViews").get(),
   142→            ]);
   143→
   144→            if (extActionsSnap.empty) {
   145→              throw new NotFoundError("External feedback actions");
   146→            }
   147→            if (extViewsSnap.empty) {
   148→              throw new NotFoundError("External feedback views");
   149→            }
   150→
   151→            const actions = await Promise.all(
   152→              extActionsSnap.docs.map(async (action) => {
   153→                const id = action.id;
   154→                const data = action.data();
   155→
   156→                const [feedbackActionData, templateActionData] =
   157→                  await Promise.all([
   158→                    getExtActionData(
   159→                      `Buildings/${queryParams.buildingId}/externalFeedbackActions/${id}`
   160→                    ),
   161→                    data.template
   162→                      ? getExtActionData(
   163→                          data.template?._path?.segments?.join("/")
   164→                        )
   165→                      : Promise.resolve({}),
   166→                  ]);
   167→
   168→                return { ...templateActionData, ...feedbackActionData };
   169→              })
   170→            );
   171→
   172→            actionData = actions.find((a) => a.id === queryParams.extActionId);
   173→
   174→            const views = extViewsSnap.docs.map((view) => ({
   175→              id: view.id,
   176→              ...view.data(),
   177→            }));
   178→
   179→            return [actions, views] as [any[], any[]];
   180→          }
   181→        );
   182→      }
   183→
   184→      // Track 'open' event in session
