    19→const THUMBNAIL_SIZE = 200;
    20→const SUPPORTED_IMAGE_TYPES = [
    21→  "image/jpeg",
    22→  "image/jpg",
    23→  "image/png",
    24→  "image/webp",
    25→  "image/gif",
    26→  "image/bmp",
    27→  "image/tiff",
    28→];
    29→const SUPPORTED_IMAGE_EXTENSIONS = new Set([
    30→  ".jpg",
    31→  ".jpeg",
    32→  ".png",
    33→  ".webp",
    34→  ".gif",
    35→  ".bmp",
    36→  ".tiff",
    37→  ".tif",
    38→]);
    39→const SUPPORTED_VIDEO_TYPES = [
    40→  "video/mp4",
    41→  "video/quicktime",
    42→  "video/x-msvideo",
    43→  "video/x-matroska",
    44→  "video/webm",
    45→  "video/mpeg",
    46→];
    47→const SUPPORTED_VIDEO_EXTENSIONS = new Set([
    48→  ".mp4",
    49→  ".mov",
    50→  ".avi",
    51→  ".mkv",
    52→  ".webm",
    53→  ".mpeg",
    54→  ".mpg",
    55→]);
    56→const SUPPORTED_PDF_TYPES = ["application/pdf"];
    57→const SUPPORTED_PDF_EXTENSIONS = new Set([".pdf"]);
