import * as functions from "firebase-functions/v2";
import { StorageEvent } from "firebase-functions/v2/storage";
import * as admin from "firebase-admin";
import * as path from "path";
import * as os from "os";
import * as fs from "fs/promises";
import { spawn } from "node:child_process";
import sharp from "sharp";
import ffmpegPath from "ffmpeg-static";
import { getFirestore } from "firebase-admin/firestore";
import { collectionNames, ActionFile } from "@ofrules/checkpoint-ts-common";
import { createCanvas } from "canvas";
// pdfjs-dist v3 ships a CommonJS build; v4+ is ESM-only so we pin to v3.
import * as pdfjs from "pdfjs-dist/legacy/build/pdf.js";

// Disable the PDF.js worker — not needed in the Cloud Function environment.
pdfjs.GlobalWorkerOptions.workerSrc = "";

const THUMBNAIL_SIZE = 200;
const SUPPORTED_IMAGE_TYPES = [
  "image/jpeg",
  "image/jpg",
  "image/png",
  "image/webp",
  "image/gif",
  "image/bmp",
  "image/tiff",
];
const SUPPORTED_IMAGE_EXTENSIONS = new Set([
  ".jpg",
  ".jpeg",
  ".png",
  ".webp",
  ".gif",
  ".bmp",
  ".tiff",
  ".tif",
]);
const SUPPORTED_VIDEO_TYPES = [
  "video/mp4",
  "video/quicktime",
  "video/x-msvideo",
  "video/x-matroska",
  "video/webm",
  "video/mpeg",
];
const SUPPORTED_VIDEO_EXTENSIONS = new Set([
  ".mp4",
  ".mov",
  ".avi",
  ".mkv",
  ".webm",
  ".mpeg",
  ".mpg",
]);
const SUPPORTED_PDF_TYPES = ["application/pdf"];
const SUPPORTED_PDF_EXTENSIONS = new Set([".pdf"]);

/**
 * Generates thumbnails for images and videos uploaded to Firebase Storage.
 * Triggers on file upload to: app/private/buildings/{buildingId}/occurrences/{occurrenceId}/{id}_{filename}
 * Saves thumbnails to the same directory as the original file, with a `_200x200` suffix added
 * before the extension (e.g. `myimage_200x200.jpg`). Videos produce a `_200x200.jpg` still frame.
 */
export async function generateThumbnailsHandler(
  event: StorageEvent
): Promise<null> {
  const filePath = event.data.name;

  // Guard against missing file name (valid in the Storage event type but would crash below)
  if (!filePath) return null;

  // Silently ignore thumbnails and any file outside the known permanent paths
  // (occurrence attachments or guest-action attachments). Staging uploads and
  // unrelated bucket objects are skipped without logging.
  const pathPattern =
    /^app\/private\/buildings\/[^/]+\/(occurrences|guestActions)\/[^/]+\/[^/]+$/;
  if (
    filePath.includes(`_${THUMBNAIL_SIZE}x${THUMBNAIL_SIZE}`) ||
    !pathPattern.test(filePath)
  ) {
    return null;
  }

  const contentType = event.data.contentType;

  functions.logger.info("Processing file", { filePath, contentType });

  // Check if file type is supported. Some clients (e.g. Android) upload files
  // with a generic "application/octet-stream" content type, so fall back to
  // the file extension when the MIME type is not a recognised image/video type.
  const ext = path.extname(filePath).toLowerCase();
  const isImage =
    (contentType && SUPPORTED_IMAGE_TYPES.includes(contentType)) ??
    SUPPORTED_IMAGE_EXTENSIONS.has(ext);
  const isVideo =
    !isImage &&
    ((contentType && SUPPORTED_VIDEO_TYPES.includes(contentType)) ??
      SUPPORTED_VIDEO_EXTENSIONS.has(ext));
  const isPdf =
    !isImage &&
    !isVideo &&
    ((contentType && SUPPORTED_PDF_TYPES.includes(contentType)) ??
      SUPPORTED_PDF_EXTENSIONS.has(ext));

  if (!isImage && !isVideo && !isPdf) {
    functions.logger.info("Unsupported file type, skipping");

    return null;
  }

  // Read action metadata from the Storage event — set by moveAttachments when
  // copying the file to its permanent location. No extra getMetadata() call needed.
  const customMetadata = event.data.metadata as
    | Record<string, string>
    | undefined;
  const actionID = customMetadata?.actionID;

  // Parse path parts: app/private/buildings/{buildingID}/{entityType}/{entityID}/{id}_{filename}
  const pathParts = filePath.split("/");
  const buildingID = pathParts[3];
  const entityType = pathParts[4]; // "occurrences" | "guestActions"
  const entityID = pathParts[5];
  const fileSegment = pathParts[6];
  const fileId = fileSegment.substring(0, fileSegment.indexOf("_"));

  // Resolve the Firestore action reference based on entity type.
  const db = getFirestore();
  let actionRef: FirebaseFirestore.DocumentReference;

  if (entityType === "guestActions") {
    const guestActionID = customMetadata?.guestActionID;
    if (!guestActionID || !actionID) {
      functions.logger.info(
        "No guest action metadata on file, skipping Firestore update",
        { filePath }
      );

      return null;
    }
    actionRef = db
      .collection(collectionNames.buildingsCN)
      .doc(buildingID)
      .collection(collectionNames.externalUserActionsCN)
      .doc(guestActionID)
      .collection(collectionNames.actionsCN)
      .doc(actionID);
  } else {
    // occurrences
    const checkpointID = customMetadata?.checkpointID;
    if (!checkpointID || !actionID) {
      functions.logger.info(
        "No action metadata on file, skipping Firestore update",
        { filePath }
      );

      return null;
    }
    actionRef = db
      .collection(collectionNames.buildingsCN)
      .doc(buildingID)
      .collection(collectionNames.checkpointsCN)
      .doc(checkpointID)
      .collection(collectionNames.occurrencesCN)
      .doc(entityID)
      .collection(collectionNames.actionsCN)
      .doc(actionID);
  }

  const actionSnap = await actionRef.get();
  if (!actionSnap.exists) {
    functions.logger.info("Action not found, skipping thumbnail generation", {
      buildingID,
      entityType,
      entityID,
      actionID,
    });

    return null;
  }

  const bucket = admin.storage().bucket(event.data.bucket);
  const fileName = path.basename(filePath);
  const tempFilePath = path.join(os.tmpdir(), fileName);

  try {
    // Download file to temp directory
    functions.logger.info("Downloading file to temp directory");
    await bucket.file(filePath).download({ destination: tempFilePath });

    let thumbnailBuffer: Buffer;

    if (isImage) {
      functions.logger.info("Processing image");
      thumbnailBuffer = await sharp(tempFilePath)
        .resize(THUMBNAIL_SIZE, THUMBNAIL_SIZE, {
          fit: "cover",
          position: "center",
        })
        .jpeg({ quality: 85 })
        .toBuffer();
    } else if (isPdf) {
      functions.logger.info("Processing PDF");
      thumbnailBuffer = await extractPdfThumbnail(tempFilePath);
    } else {
      // isVideo
      functions.logger.info("Processing video");
      thumbnailBuffer = await extractVideoFrame(tempFilePath);
    }

    // Thumbnail path: same directory as the original, with `_200x200` appended before the extension.
    // For image.jpg -> image_200x200.jpg
    // For video.mp4 -> video_200x200.jpg (JPEG still frame)
    const fileExt = path.extname(fileName);
    const nameWithoutExt = path.basename(fileName, fileExt);
    const thumbnailFileName = `${nameWithoutExt}_${THUMBNAIL_SIZE}x${THUMBNAIL_SIZE}.jpg`;
    const thumbnailPath = path.join(path.dirname(filePath), thumbnailFileName);

    functions.logger.info("Uploading thumbnail", {
      path: thumbnailPath,
    });

    // Upload thumbnail
    const thumbnailFile = bucket.file(thumbnailPath);
    await thumbnailFile.save(thumbnailBuffer, {
      metadata: {
        contentType: "image/jpeg",
        metadata: {
          originalFile: filePath,
        },
      },
    });

    functions.logger.info("Thumbnail generated successfully");

    // Update the action document with the thumbnail path.
    // Re-use the already-fetched actionSnap data to avoid an extra read.
    const files = (actionSnap.data()?.files ?? []) as ActionFile[];
    const updatedFiles = files.map((f) =>
      f.id === fileId ? { ...f, thumbnailPath } : f
    );

    await actionRef.update({ files: updatedFiles });

    functions.logger.info("Updated action with thumbnail path", {
      actionID,
      fileId,
      thumbnailPath,
    });

    return null;
  } catch (error) {
    functions.logger.error("Error generating thumbnail:", error);
    throw error;
  } finally {
    // Clean up temp file
    try {
      await fs.unlink(tempFilePath);
    } catch (error) {
      functions.logger.warn("Error cleaning up temp file:", error);
    }
  }
}

/**
 * Renders the first page of a PDF file and returns a JPEG thumbnail buffer.
 */
async function extractPdfThumbnail(filePath: string): Promise<Buffer> {
  const data = new Uint8Array(await fs.readFile(filePath));

  const pdfDoc = await pdfjs.getDocument({
    data,
    useWorkerFetch: false,
    isEvalSupported: false,
    useSystemFonts: true,
  }).promise;

  const page = await pdfDoc.getPage(1);
  // Render at scale 1 (72 dpi). A standard A4 page is ~595×842 px — well
  // above the thumbnail size, so downscaling gives good quality.
  const viewport = page.getViewport({ scale: 1 });

  const canvas = createCanvas(
    Math.round(viewport.width),
    Math.round(viewport.height)
  );
  const context = canvas.getContext("2d");
  await page.render({
    canvasContext: context as unknown as CanvasRenderingContext2D,
    viewport,
  }).promise;

  return (
    sharp(canvas.toBuffer("image/png"))
      // Strip the typical white margins so the actual content fills the frame.
      .trim({ background: "#ffffff", threshold: 10 })
      // Shrink the content to fit within the square without cropping any of it.
      // White bars are added on the shorter axis to produce a 200×200 image.
      .resize(THUMBNAIL_SIZE, THUMBNAIL_SIZE, {
        fit: "contain",
        background: "#ffffff",
      })
      .jpeg({ quality: 85 })
      .toBuffer()
  );
}

/**
 * Extracts a frame from a video file and resizes it to thumbnail size
 */
async function extractVideoFrame(videoPath: string): Promise<Buffer> {
  if (!ffmpegPath) {
    throw new Error("ffmpeg-static path not found");
  }

  const tempFramePath = `${videoPath}_frame.jpg`;

  try {
    // Extract frame at 1 second using ffmpeg
    await new Promise<void>((resolve, reject) => {
      const ffmpegProcess = spawn(ffmpegPath as string, [
        "-i",
        videoPath,
        "-ss",
        "00:00:01",
        "-vframes",
        "1",
        "-vf",
        `scale=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}:force_original_aspect_ratio=increase,crop=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}`,
        "-q:v",
        "2",
        tempFramePath,
      ]);

      let errorOutput = "";

      ffmpegProcess.stderr.on("data", (data: Buffer) => {
        errorOutput += data.toString();
      });

      ffmpegProcess.on("close", (code: number | null) => {
        if (code === 0) {
          resolve();
        } else {
          reject(
            new Error(`ffmpeg process exited with code ${code}: ${errorOutput}`)
          );
        }
      });

      ffmpegProcess.on("error", (err: Error) => {
        reject(err);
      });
    });

    // Read and optimize with sharp
    const thumbnailBuffer = await sharp(tempFramePath)
      .jpeg({ quality: 85 })
      .toBuffer();

    return thumbnailBuffer;
  } finally {
    // Clean up temp frame file
    try {
      await fs.unlink(tempFramePath);
    } catch (error) {
      functions.logger.warn("Error cleaning up temp frame file:", error);
    }
  }
}

import { getStorage, ref, getDownloadURL } from 'firebase/storage'
import { firebaseApp } from '@/services/firebase-config'

const storage = getStorage(firebaseApp)

/**
 * Get download URL for a Firebase Storage file
 * @param gsUrl - Firebase Storage URL in format: gs://bucket-name/path/to/file
 * @returns Promise with the download URL
 */
export async function getStorageUrl(gsUrl: string): Promise<string> {
  try {
    // Extract the path from gs:// URL
    const path = gsUrl.replace(/^gs:\/\/[^/]+\//, '')

    const storageRef = ref(storage, path)
    const url = await getDownloadURL(storageRef)

    return url
  } catch (error) {
    console.error('Error getting storage URL:', error)
    throw error
  }
}

/**
 * Convert gs:// URL to https:// URL without authentication (for public files)
 * @param gsUrl - Firebase Storage URL in format: gs://bucket-name/path/to/file
 * @returns HTTPS URL
 */
export function gsToHttps(gsUrl: string): string {
  // Extract bucket and path from gs:// URL
  const match = gsUrl.match(/^gs:\/\/([^/]+)\/(.+)$/)

  if (!match) {
    return gsUrl
  }

  const [, bucket, path] = match
  const encodedPath = path.split('/').map(encodeURIComponent).join('%2F')

  return `https://firebasestorage.googleapis.com/v0/b/${bucket}/o/${encodedPath}?alt=media`
}

