const occurrencePathPattern =
  /^app\/private\/buildings\/[^/]+\/(occurrences|guestActions)\/[^/]+\/[^/]+$/;

const isOccurrencePath = occurrencePathPattern.test(filePath);
const isGuestPortalPath = guestPortalPathPattern.test(filePath);

if (
  filePath.includes(`_${THUMBNAIL_SIZE}x${THUMBNAIL_SIZE}`) ||
