// Guest portal images: generate thumbnail and return — no Firestore write-back.
if (isGuestPortalPath) {
  if (!isImage) {
    functions.logger.info("Guest portal file is not an image, skipping");
    return null;
  }

  const bucket = admin.storage().bucket(event.data.bucket);
  const fileName = path.basename(filePath);
  const tempFilePath = path.join(os.tmpdir(), fileName);

