   328→/**
   329→ * Renders the first page of a PDF file and returns a JPEG thumbnail buffer.
   330→ */
   331→async function extractPdfThumbnail(filePath: string): Promise<Buffer> {
   332→  const data = new Uint8Array(await fs.readFile(filePath));
   333→
   334→  const pdfDoc = await pdfjs.getDocument({
   335→    data,
   336→    useWorkerFetch: false,
   337→    isEvalSupported: false,
   338→    useSystemFonts: true,
   339→  }).promise;
   340→
   341→  const page = await pdfDoc.getPage(1);
   342→  // Render at scale 1 (72 dpi). A standard A4 page is ~595×842 px — well
   343→  // above the thumbnail size, so downscaling gives good quality.
   344→  const viewport = page.getViewport({ scale: 1 });
   345→
   346→  const canvas = createCanvas(
   347→    Math.round(viewport.width),
   348→    Math.round(viewport.height)
   349→  );
   350→  const context = canvas.getContext("2d");
   351→  await page.render({
   352→    canvasContext: context as unknown as CanvasRenderingContext2D,
   353→    viewport,
   354→  }).promise;
   355→
   356→  return (
   357→    sharp(canvas.toBuffer("image/png"))
   358→      // Strip the typical white margins so the actual content fills the frame.
   359→      .trim({ background: "#ffffff", threshold: 10 })
   360→      // Shrink the content to fit within the square without cropping any of it.
   361→      // White bars are added on the shorter axis to produce a 200×200 image.
   362→      .resize(THUMBNAIL_SIZE, THUMBNAIL_SIZE, {
   363→        fit: "contain",
   364→        background: "#ffffff",
   365→      })
   366→      .jpeg({ quality: 85 })
   367→      .toBuffer()
   368→  );
   369→}
