   371→/**
   372→ * Extracts a frame from a video file and resizes it to thumbnail size
   373→ */
   374→async function extractVideoFrame(videoPath: string): Promise<Buffer> {
   375→  if (!ffmpegPath) {
   376→    throw new Error("ffmpeg-static path not found");
   377→  }
   378→
   379→  const tempFramePath = `${videoPath}_frame.jpg`;
   380→
   381→  try {
   382→    // Extract frame at 1 second using ffmpeg
   383→    await new Promise<void>((resolve, reject) => {
   384→      const ffmpegProcess = spawn(ffmpegPath as string, [
   385→        "-i",
   386→        videoPath,
   387→        "-ss",
   388→        "00:00:01",
   389→        "-vframes",
   390→        "1",
   391→        "-vf",
   392→        `scale=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}:force_original_aspect_ratio=increase,crop=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}`,
   393→        "-q:v",
   394→        "2",
   395→        tempFramePath,
   396→      ]);
   397→
   398→      let errorOutput = "";
   399→
   400→      ffmpegProcess.stderr.on("data", (data: Buffer) => {
   401→        errorOutput += data.toString();
   402→      });
   403→
   404→      ffmpegProcess.on("close", (code: number | null) => {
   405→        if (code === 0) {
   406→          resolve();
   407→        } else {
   408→          reject(
   409→            new Error(`ffmpeg process exited with code ${code}: ${errorOutput}`)
   410→          );
   411→        }
   412→      });
   413→
   414→      ffmpegProcess.on("error", (err: Error) => {
   415→        reject(err);
   416→      });
   417→    });
   418→
   419→    // Read and optimize with sharp
   420→    const thumbnailBuffer = await sharp(tempFramePath)
   421→      .jpeg({ quality: 85 })
   422→      .toBuffer();
   423→
   424→    return thumbnailBuffer;
   425→  } finally {
