   111→    !isImage &&
   112→    !isVideo &&
   113→    ((contentType && SUPPORTED_PDF_TYPES.includes(contentType)) ??
   114→      SUPPORTED_PDF_EXTENSIONS.has(ext));
   115→
   116→  if (!isImage && !isVideo && !isPdf) {
   117→    functions.logger.info("Unsupported file type, skipping");
