   119→    return null;
   120→  }
   121→
   122→  // Guest portal images: generate thumbnail and return — no Firestore write-back.
   123→  if (isGuestPortalPath) {
   124→    if (!isImage) {
   125→      functions.logger.info("Guest portal file is not an image, skipping");
