   331→/**
   332→ * Renders the first page of a PDF file and returns a JPEG thumbnail buffer.
   333→ */
   334→async function extractPdfThumbnail(filePath: string): Promise<Buffer> {
   335→  const data = new Uint8Array(await fs.readFile(filePath));
   336→
   337→  const pdfDoc = await pdfjs.getDocument({
   338→    data,
   339→    useWorkerFetch: false,
   340→    isEvalSupported: false,
   341→    useSystemFonts: true,
   342→  }).promise;
   343→
   344→  const page = await pdfDoc.getPage(1);
   345→  // Render at scale 1 (72 dpi). A standard A4 page is ~595×842 px — well
   346→  // above the thumbnail size, so downscaling gives good quality.
   347→  const viewport = page.getViewport({ scale: 1 });
   348→
   349→  const canvas = createCanvas(
   350→    Math.round(viewport.width),
   351→    Math.round(viewport.height)
   352→  );
   353→  const context = canvas.getContext("2d");
   354→  await page.render({
   355→    canvasContext: context as unknown as CanvasRenderingContext2D,
   356→    viewport,
   357→  }).promise;
   358→
   359→  return (
   360→    sharp(canvas.toBuffer("image/png"))
   361→      // Strip the typical white margins so the actual content fills the frame.
   362→      .trim({ background: "#ffffff", threshold: 10 })
   363→      // Shrink the content to fit within the square without cropping any of it.
   364→      // White bars are added on the shorter axis to produce a 200×200 image.
   365→      .resize(THUMBNAIL_SIZE, THUMBNAIL_SIZE, {
   366→        fit: "contain",
   367→        background: "#ffffff",
   368→      })
   369→      .jpeg({ quality: 85 })
   370→      .toBuffer()
   371→  );
   372→}
   373→
   374→/**
   375→ * Extracts a frame from a video file and resizes it to thumbnail size
   376→ */
   377→async function extractVideoFrame(videoPath: string): Promise<Buffer> {
   378→  if (!ffmpegPath) {
   379→    throw new Error("ffmpeg-static path not found");
   380→  }
   381→
   382→  const tempFramePath = `${videoPath}_frame.jpg`;
   383→
   384→  try {
   385→    // Extract frame at 1 second using ffmpeg
   386→    await new Promise<void>((resolve, reject) => {
   387→      const ffmpegProcess = spawn(ffmpegPath as string, [
   388→        "-i",
   389→        videoPath,
   390→        "-ss",
   391→        "00:00:01",
   392→        "-vframes",
   393→        "1",
   394→        "-vf",
   395→        `scale=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}:force_original_aspect_ratio=increase,crop=${THUMBNAIL_SIZE}:${THUMBNAIL_SIZE}`,
   396→        "-q:v",
   397→        "2",
   398→        tempFramePath,
   399→      ]);
   400→
   401→      let errorOutput = "";
   402→
   403→      ffmpegProcess.stderr.on("data", (data: Buffer) => {
   404→        errorOutput += data.toString();
   405→      });
   406→
   407→      ffmpegProcess.on("close", (code: number | null) => {
   408→        if (code === 0) {
   409→          resolve();
   410→        } else {
   411→          reject(
   412→            new Error(`ffmpeg process exited with code ${code}: ${errorOutput}`)
   413→          );
   414→        }
   415→      });
   416→
   417→      ffmpegProcess.on("error", (err: Error) => {
   418→        reject(err);
   419→      });
   420→    });
   421→
   422→    // Read and optimize with sharp
   423→    const thumbnailBuffer = await sharp(tempFramePath)
   424→      .jpeg({ quality: 85 })
   425→      .toBuffer();
   426→
   427→    return thumbnailBuffer;
   428→  } finally {
   429→    // Clean up temp frame file
   430→    try {
   431→      await fs.unlink(tempFramePath);
   432→    } catch (error) {
   433→      functions.logger.warn("Error cleaning up temp frame file:", error);
   434→    }
   435→  }
   436→}
